import { useId, type SVGProps } from 'react'

import { cx } from '../utils'

export type WeaponIconId =
  | 'pulse-carbine'
  | 'micro-missile'
  | 'scatter-cannon'
  | 'railgun'
  | 'orbit-drone'
  | 'arc-emitter'
  | 'generic-ranged'

export interface WeaponIconProps extends Omit<
  SVGProps<SVGSVGElement>,
  'children'
> {
  id: WeaponIconId
  title?: string
}

/**
 * Code-native weapon glyphs shared by the build HUD and level-up cards.
 * Every mark inherits `currentColor`, so rarity and equipped-state colours
 * stay in CSS instead of being baked into assets.
 */
export function WeaponIcon({
  id,
  title,
  className,
  ...svgProps
}: WeaponIconProps) {
  const titleId = useId()
  const stroke = {
    fill: 'none',
    stroke: 'currentColor',
    strokeWidth: 3.25,
    strokeLinecap: 'round' as const,
    strokeLinejoin: 'round' as const,
  }

  const glyph = (() => {
    switch (id) {
      case 'pulse-carbine':
        return (
          <>
            <path {...stroke} d="M8 26h31l8 6h9v8H35l-7 10H17l5-10H8V26Z" />
            <path {...stroke} d="M18 26v-7h15l6 7M43 32h7M25 40l6 5" />
            <circle cx="14" cy="33" r="2.5" fill="currentColor" />
          </>
        )
      case 'micro-missile':
        return (
          <>
            <path
              {...stroke}
              d="M14 42c12-21 23-29 37-29 0 14-8 25-29 37l-8-8Z"
            />
            <path {...stroke} d="m23 48-12 5 5-12m7-8 8 8" />
            <circle cx="41" cy="23" r="4" fill="currentColor" />
            <path {...stroke} d="M11 55 5 59m13-2-4 4" />
          </>
        )
      case 'scatter-cannon':
        return (
          <>
            <path {...stroke} d="M8 23h34l12 7v10L42 47H8V23Z" />
            <path {...stroke} d="M42 28h14M42 35h14M42 42h14" />
            <path {...stroke} d="m21 47 6 10h11l-3-10M16 30h18" />
          </>
        )
      case 'railgun':
        return (
          <>
            <path {...stroke} d="M5 29h43l10 5-10 5H5V29Z" />
            <path {...stroke} d="M13 22h34v7M17 39l7 13h11l-3-13" />
            <path {...stroke} d="M49 26v16M8 34h35" />
          </>
        )
      case 'orbit-drone':
        return (
          <>
            <circle {...stroke} cx="32" cy="32" r="10" />
            <circle cx="32" cy="32" r="3.5" fill="currentColor" />
            <path
              {...stroke}
              d="M8 32c0-11 11-20 24-20s24 9 24 20-11 20-24 20S8 43 8 32Z"
            />
            <path {...stroke} d="M16 15 9 9m39 6 7-6M16 49l-7 6m39-6 7 6" />
            <circle cx="12" cy="22" r="3" fill="currentColor" />
            <circle cx="52" cy="42" r="3" fill="currentColor" />
          </>
        )
      case 'arc-emitter':
        return (
          <>
            <path {...stroke} d="M18 9 8 29h16l-7 26 30-34H31l8-12" />
            <path
              {...stroke}
              d="M42 34c6 2 10 6 10 11M44 27c10 3 16 10 16 19"
            />
          </>
        )
      default:
        return (
          <>
            <circle {...stroke} cx="32" cy="32" r="16" />
            <circle {...stroke} cx="32" cy="32" r="5" />
            <path {...stroke} d="M32 7v12m0 26v12M7 32h12m26 0h12" />
          </>
        )
    }
  })()

  return (
    <svg
      {...svgProps}
      className={cx('ss-build-icon ss-build-icon--weapon', className)}
      viewBox="0 0 64 64"
      role={title ? 'img' : undefined}
      aria-hidden={title ? undefined : true}
      aria-labelledby={title ? titleId : undefined}
      focusable="false"
      data-weapon-icon={id}
    >
      {title ? <title id={titleId}>{title}</title> : null}
      {glyph}
    </svg>
  )
}
