import { useEffect, useRef } from 'react'

export interface TitleScreenProps {
  onStart: () => void
  onContinue?: () => void
  onOpenSettings?: () => void
  title?: string
  eyebrow?: string
  subtitle?: string
  description?: string
  version?: string
  busy?: boolean
  desktopArtSrc?: string
  mobileArtSrc?: string
  logoSrc?: string
  anyKeyLabel?: string
  statusLabel?: string
}

export function TitleScreen({
  onStart,
  onContinue,
  onOpenSettings,
  title = 'STILLSEEN',
  eyebrow = 'ENDLESS SURVIVAL PROTOCOL',
  subtitle = '자동 무장을 구축하고, 끝없이 살아남아라',
  description = '세 개의 무기 슬롯을 완성하고 몰려드는 기계 군단을 돌파하세요.',
  version,
  busy = false,
  desktopArtSrc,
  mobileArtSrc,
  logoSrc,
  anyKeyLabel = 'COMMAND DECK 접속',
  statusLabel = '게임 시작 화면',
}: TitleScreenProps) {
  const activatedRef = useRef(false)
  const activate = onContinue ?? onStart

  useEffect(() => {
    activatedRef.current = false
  }, [busy, activate])

  const handleActivate = () => {
    if (busy || activatedRef.current) return
    activatedRef.current = true
    activate()
  }

  return (
    <main
      className="stillseen-ui stillseen-title stillseen-title--keyart"
      data-testid="title-screen"
      aria-label={statusLabel}
      aria-busy={busy}
    >
      {desktopArtSrc ? (
        <picture
          className="stillseen-title__keyart"
          aria-hidden="true"
          data-testid="title-keyart"
        >
          {mobileArtSrc ? (
            <source media="(max-width: 700px)" srcSet={mobileArtSrc} />
          ) : null}
          <img src={desktopArtSrc} alt="" draggable={false} />
        </picture>
      ) : null}
      <div className="stillseen-title__mist" aria-hidden="true" />
      <div className="stillseen-title__vignette" aria-hidden="true" />

      <section
        className="stillseen-title__content"
        aria-labelledby="stillseen-game-title"
      >
        <p className="stillseen-eyebrow">{eyebrow}</p>
        <h1 id="stillseen-game-title" className="stillseen-title__name">
          {logoSrc ? (
            <>
              <img
                className="stillseen-title__logo"
                src={logoSrc}
                alt=""
                draggable={false}
              />
              <span className="stillseen-sr-only">{title}</span>
            </>
          ) : (
            title
          )}
        </h1>
        <div className="stillseen-ornament" aria-hidden="true">
          <span />
          <i />
          <span />
        </div>
        <p className="stillseen-title__subtitle">{subtitle}</p>
        <p className="stillseen-title__description">{description}</p>

        <button
          type="button"
          className="stillseen-title__enter"
          onClick={handleActivate}
          disabled={busy}
          data-testid="start-game-button"
        >
          <span className="stillseen-title__enter-label">
            {busy ? '시스템 준비 중…' : anyKeyLabel}
          </span>
        </button>
        {onContinue ? (
          <span
            className="stillseen-sr-only"
            data-testid="continue-game-button"
          >
            계속하기
          </span>
        ) : null}
      </section>

      <p className="stillseen-title__hint">헤드폰 사용을 권장합니다</p>
      {onOpenSettings ? (
        <button
          type="button"
          className="stillseen-title__settings"
          onClick={onOpenSettings}
          disabled={busy}
          data-testid="open-settings-button"
        >
          설정
        </button>
      ) : null}
      {version ? <p className="stillseen-title__version">{version}</p> : null}
    </main>
  )
}
