import { useEffect } from 'react'

import type { RangedWeaponId } from '../../game/runBuild'
import { WeaponIcon, type WeaponIconId } from './WeaponIcon'
import './starter-weapon.css'

export interface StarterWeaponChoice {
  readonly id: RangedWeaponId
  readonly name: string
  readonly description: string
  readonly iconId: WeaponIconId
  readonly damage: number
  readonly cooldownMs: number
  readonly range: number
  readonly role: string
}

export function StarterWeaponOverlay({
  choices,
  onSelect,
  onCancel,
}: {
  readonly choices: readonly StarterWeaponChoice[]
  readonly onSelect: (weaponId: RangedWeaponId) => void
  readonly onCancel: () => void
}) {
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') onCancel()
    }
    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [onCancel])

  return (
    <div className="ss-starter-weapon" role="presentation">
      <section
        className="ss-starter-weapon__panel"
        role="dialog"
        aria-modal="true"
        aria-labelledby="ss-starter-weapon-title"
        data-testid="starter-weapon-overlay"
      >
        <header>
          <p>DEPLOYMENT LOADOUT · 01</p>
          <h2 id="ss-starter-weapon-title">시작 무기를 선택하세요</h2>
          <span>
            선택한 무기 하나로 출전합니다. 모든 무기는 적을 감지해 자동으로
            공격합니다.
          </span>
        </header>

        <div className="ss-starter-weapon__grid">
          {choices.map((choice, index) => (
            <button
              key={choice.id}
              type="button"
              className="ss-starter-weapon__card"
              onClick={() => onSelect(choice.id)}
              autoFocus={index === 0}
              data-testid={`starter-weapon-${choice.id}`}
            >
              <span className="ss-starter-weapon__icon" aria-hidden="true">
                <WeaponIcon id={choice.iconId} />
              </span>
              <span className="ss-starter-weapon__copy">
                <small>{choice.role}</small>
                <strong>{choice.name}</strong>
                <span>{choice.description}</span>
              </span>
              <dl>
                <div>
                  <dt>피해</dt>
                  <dd>{choice.damage}</dd>
                </div>
                <div>
                  <dt>발사 간격</dt>
                  <dd>{(choice.cooldownMs / 1000).toFixed(2)}초</dd>
                </div>
                <div>
                  <dt>사거리</dt>
                  <dd>{choice.range.toFixed(1)}m</dd>
                </div>
              </dl>
              <span className="ss-starter-weapon__select">이 무기로 출전</span>
            </button>
          ))}
        </div>

        <button
          type="button"
          className="ss-starter-weapon__cancel"
          onClick={onCancel}
        >
          로비로 돌아가기
        </button>
      </section>
    </div>
  )
}
