import { useEffect, useRef, useState, type CSSProperties } from 'react'

import { clamp, cx } from '../utils'
import { PassiveIcon, type PassiveIconId } from './PassiveIcon'
import { WeaponIcon, type WeaponIconId } from './WeaponIcon'
import './build-ui.css'

export interface BaseWeaponSlotViewModel {
  readonly id: string
  readonly name: string
  readonly iconId: WeaponIconId
  readonly level: number
  readonly maxLevel?: number
  /** Normalized recharge progress: 0 just fired, 1 ready. */
  readonly cooldownProgress: number
}

export interface RangedWeaponSlotViewModel extends BaseWeaponSlotViewModel {
  readonly category: 'ranged'
}

/** Four auto-firing weapon positions; unfilled positions are null. */
export type RunWeaponSlots = readonly [
  RangedWeaponSlotViewModel | null,
  RangedWeaponSlotViewModel | null,
  RangedWeaponSlotViewModel | null,
  RangedWeaponSlotViewModel | null,
]

export interface PassiveStackViewModel {
  readonly id: string
  readonly name: string
  readonly iconId: PassiveIconId
  readonly stacks: number
}

export interface RunBuildHudProps {
  readonly health: number
  readonly maxHealth: number
  readonly armor: number
  readonly regenerationPerSecond: number
  readonly experience: number
  readonly experienceRequired: number
  readonly level: number
  readonly elapsedSeconds: number
  readonly nextBossInSeconds: number | null
  readonly weapons: RunWeaponSlots
  readonly passives: readonly PassiveStackViewModel[]
  readonly className?: string
}

export const MAX_VISIBLE_PASSIVES = 12

function formatClock(seconds: number): string {
  const safe = Math.max(0, Math.floor(Number.isFinite(seconds) ? seconds : 0))
  const minutes = Math.floor(safe / 60)
  return `${String(minutes).padStart(2, '0')}:${String(safe % 60).padStart(2, '0')}`
}

function WeaponSlot({
  weapon,
  index,
}: {
  weapon: RunWeaponSlots[number]
  index: number
}) {
  const slotLabel = `자동 무기 ${index + 1}`
  if (!weapon) {
    return (
      // Empty slots carry the same testid as filled ones. A run opens with three
      // of them, so the HUD's most common state would otherwise be the one
      // state nothing could address.
      <li
        className="ss-build-weapon-slot"
        data-empty="true"
        aria-label={`${slotLabel} 슬롯 비어 있음`}
        data-testid={`build-weapon-slot-${index}`}
      >
        <span className="ss-build-weapon-slot__index">0{index + 1}</span>
        <span className="ss-build-weapon-slot__empty">EMPTY</span>
      </li>
    )
  }

  const cooldown = clamp(weapon.cooldownProgress, 0, 1)
  const style = {
    '--ss-build-cooldown': `${Math.round(cooldown * 100)}%`,
  } as CSSProperties
  const level = Math.max(1, Math.floor(weapon.level))

  return (
    <li
      className="ss-build-weapon-slot"
      data-category={weapon.category}
      data-ready={cooldown >= 0.999}
      aria-label={`${slotLabel}, ${weapon.name}, 레벨 ${level}${cooldown >= 0.999 ? ', 준비됨' : ', 재충전 중'}`}
      data-testid={`build-weapon-slot-${index}`}
    >
      <span className="ss-build-weapon-slot__index">0{index + 1}</span>
      <span className="ss-build-weapon-slot__icon" style={style}>
        <WeaponIcon id={weapon.iconId} />
        <i aria-hidden="true" />
      </span>
      <span className="ss-build-weapon-slot__copy">
        <small>{slotLabel}</small>
        <strong>{weapon.name}</strong>
      </span>
      <span className="ss-build-weapon-slot__level">
        LV {level}
        {weapon.maxLevel ? `/${Math.max(level, weapon.maxLevel)}` : ''}
      </span>
    </li>
  )
}

/**
 * Survivor-run HUD. It is intentionally presentation-only: the combat store
 * owns every number and passes a three-position arsenal snapshot as props.
 */
export function RunBuildHud({
  health,
  maxHealth,
  armor,
  regenerationPerSecond,
  experience,
  experienceRequired,
  level,
  elapsedSeconds,
  nextBossInSeconds,
  weapons,
  passives,
  className,
}: RunBuildHudProps) {
  const safeMaxHealth = Math.max(1, maxHealth)
  const safeHealth = clamp(health, 0, safeMaxHealth)
  const safeXpRequired = Math.max(1, experienceRequired)
  const safeExperience = clamp(experience, 0, safeXpRequired)
  const xpProgress = safeExperience / safeXpRequired
  const healthProgress = safeHealth / safeMaxHealth
  const [trailingHealth, setTrailingHealth] = useState(safeHealth)
  const [healthHitRevision, setHealthHitRevision] = useState(0)
  const previousHealth = useRef(safeHealth)
  const latestHealth = useRef(safeHealth)
  const trailingTimer = useRef<number | null>(null)

  useEffect(() => {
    latestHealth.current = safeHealth
    const prior = previousHealth.current
    previousHealth.current = safeHealth
    if (safeHealth >= prior) {
      if (trailingTimer.current === null) setTrailingHealth(safeHealth)
      return
    }
    setHealthHitRevision((revision) => revision + 1)
    if (trailingTimer.current !== null) {
      window.clearTimeout(trailingTimer.current)
    }
    trailingTimer.current = window.setTimeout(() => {
      setTrailingHealth(latestHealth.current)
      trailingTimer.current = null
    }, 550)
  }, [safeHealth])

  useEffect(
    () => () => {
      if (trailingTimer.current !== null) {
        window.clearTimeout(trailingTimer.current)
      }
    },
    [],
  )

  const trailingHealthProgress =
    clamp(trailingHealth, 0, safeMaxHealth) / safeMaxHealth
  const visiblePassives = passives.slice(0, MAX_VISIBLE_PASSIVES)
  const hiddenPassiveCount = Math.max(0, passives.length - MAX_VISIBLE_PASSIVES)

  return (
    <aside
      className={cx('ss-build-hud', className)}
      aria-label="생존 전투 상태"
      data-testid="run-build-hud"
    >
      <section
        className="ss-build-xp"
        role="progressbar"
        aria-label={`레벨 ${Math.max(1, Math.floor(level))} 경험치`}
        aria-valuemin={0}
        aria-valuemax={safeXpRequired}
        aria-valuenow={safeExperience}
        style={
          {
            '--ss-build-xp': `${Math.round(xpProgress * 100)}%`,
          } as CSSProperties
        }
      >
        <span aria-hidden="true" />
      </section>

      <section className="ss-build-vitals" aria-label="플레이어 상태">
        <header>
          <span>FRAME INTEGRITY</span>
          <strong>
            {Math.ceil(safeHealth)} <i>/</i> {Math.ceil(safeMaxHealth)}
          </strong>
        </header>
        <span
          className="ss-build-vitals__health"
          role="progressbar"
          aria-label="체력"
          aria-valuemin={0}
          aria-valuemax={safeMaxHealth}
          aria-valuenow={safeHealth}
          style={
            {
              '--ss-build-health': `${Math.round(healthProgress * 100)}%`,
              '--ss-build-health-trailing': `${Math.round(trailingHealthProgress * 100)}%`,
            } as CSSProperties
          }
        >
          <i className="ss-build-vitals__health-trailing" aria-hidden="true" />
          <i className="ss-build-vitals__health-current" aria-hidden="true" />
          {healthHitRevision > 0 ? (
            <b key={healthHitRevision} aria-hidden="true" />
          ) : null}
        </span>
        <dl>
          <div>
            <dt>방어</dt>
            <dd>{Math.max(0, Math.floor(armor))}</dd>
          </div>
          <div>
            <dt>재생</dt>
            <dd>+{Math.max(0, regenerationPerSecond).toFixed(1)}/s</dd>
          </div>
        </dl>
      </section>

      <section className="ss-build-run-status" aria-label="런 진행 상태">
        <small>SURVIVED</small>
        <time
          dateTime={`PT${Math.max(0, Math.floor(elapsedSeconds))}S`}
          data-testid="survival-value"
        >
          {formatClock(elapsedSeconds)}
        </time>
        <div>
          <strong>LV {Math.max(1, Math.floor(level))}</strong>
          <span>
            NEXT BOSS{' '}
            {nextBossInSeconds === null
              ? '--:--'
              : formatClock(nextBossInSeconds)}
          </span>
        </div>
      </section>

      <div
        className="ss-build-loadout"
        role="group"
        aria-label="장착 무기와 패시브 아이템"
        data-testid="build-loadout"
      >
        <section className="ss-build-arsenal" aria-label="장착 무기">
          <p>ARSENAL · 4 AUTO WEAPON SLOTS</p>
          <ol>
            {weapons.map((weapon, index) => (
              <WeaponSlot
                key={weapon?.id ?? `empty-${index}`}
                weapon={weapon}
                index={index}
              />
            ))}
          </ol>
        </section>

        <section className="ss-build-passives" aria-label="패시브 아이템">
          <p>PASSIVE MODULES</p>
          <ul>
            {visiblePassives.map((passive) => (
              <li
                key={passive.id}
                title={`${passive.name} ×${Math.max(1, Math.floor(passive.stacks))}`}
                aria-label={`${passive.name}, ${Math.max(1, Math.floor(passive.stacks))}중첩`}
                data-testid={`build-passive-${passive.id}`}
              >
                <PassiveIcon id={passive.iconId} />
                <span>×{Math.max(1, Math.floor(passive.stacks))}</span>
              </li>
            ))}
            {hiddenPassiveCount > 0 ? (
              <li
                className="ss-build-passives__overflow"
                aria-label={`숨겨진 패시브 ${hiddenPassiveCount}개`}
                data-testid="build-passive-overflow"
              >
                +{hiddenPassiveCount}
              </li>
            ) : null}
          </ul>
        </section>
      </div>
    </aside>
  )
}
