import { useGameStore } from '../runtime/gameStore'
import { DEFAULT_CONTROL_BINDINGS, type ControlBinding } from './controls'
import { ControlsLegend } from './screens/ControlsLegend'

const HINT_BINDING_IDS = new Set(['move', 'aim', 'dash'])

/**
 * Persistent in-combat legend: pause is omitted and descriptions are
 * stripped — the strip stays a glanceable reminder, not a tutorial. The aim
 * row reads "시야 방향" here because in the run the mouse steers where the
 * operative looks; "조준" stays the canonical label everywhere else.
 */
const HINT_BINDINGS: readonly ControlBinding[] =
  DEFAULT_CONTROL_BINDINGS.filter((binding) =>
    HINT_BINDING_IDS.has(binding.id),
  ).map((binding) => ({
    id: binding.id,
    keys: binding.keys,
    gamepadKeys: binding.gamepadKeys,
    label: binding.id === 'aim' ? '시야 방향' : binding.label,
  }))

export function GameplayControlsHint() {
  const lastInputDevice = useGameStore((state) => state.lastInputDevice)
  return (
    <ControlsLegend
      bindings={HINT_BINDINGS}
      className="ss-gameplay-hint"
      inputDevice={lastInputDevice === 'gamepad' ? 'gamepad' : 'keyboard'}
    />
  )
}
