import type { User } from 'firebase/auth'
import type { Firestore } from 'firebase/firestore'

import type { RunRecord } from './runRecords'
import {
  CLOUD_SCHEMA_VERSION,
  isLeaderboardImprovement,
  sanitizeDisplayName,
  type CloudSavePayload,
  type CloudSaveSnapshot,
  type GlobalLeaderboardEntry,
} from './cloudData'

export interface FirebaseAccount {
  readonly uid: string
  readonly displayName: string
}

interface FirebaseServices {
  readonly auth: import('firebase/auth').Auth
  readonly firestore: Firestore
}

const LEADERBOARD_CACHE_KEY = 'stillseen.leaderboard.session.v1'
let servicesPromise: Promise<FirebaseServices> | null = null

function firebaseConfig() {
  return {
    apiKey: import.meta.env.VITE_FIREBASE_API_KEY,
    authDomain: import.meta.env.VITE_FIREBASE_AUTH_DOMAIN,
    projectId: import.meta.env.VITE_FIREBASE_PROJECT_ID,
    appId: import.meta.env.VITE_FIREBASE_APP_ID,
  }
}

export function isFirebaseConfigured(): boolean {
  const config = firebaseConfig()
  return Boolean(
    config.apiKey && config.authDomain && config.projectId && config.appId,
  )
}

async function loadServices(): Promise<FirebaseServices> {
  if (!isFirebaseConfigured()) {
    throw new Error('Firebase environment variables are not configured.')
  }
  if (servicesPromise !== null) return servicesPromise

  servicesPromise = (async () => {
    const [{ getApp, getApps, initializeApp }, authModule, firestoreModule] =
      await Promise.all([
        import('firebase/app'),
        import('firebase/auth'),
        import('firebase/firestore'),
      ])
    const app =
      getApps().length > 0 ? getApp() : initializeApp(firebaseConfig())
    const auth = authModule.getAuth(app)
    const firestore = firestoreModule.getFirestore(app)

    const siteKey = import.meta.env.VITE_FIREBASE_APP_CHECK_SITE_KEY
    if (siteKey) {
      try {
        if (import.meta.env.DEV) {
          const debugToken = import.meta.env.VITE_FIREBASE_APP_CHECK_DEBUG_TOKEN
          ;(
            globalThis as typeof globalThis & {
              FIREBASE_APPCHECK_DEBUG_TOKEN?: boolean | string
            }
          ).FIREBASE_APPCHECK_DEBUG_TOKEN = debugToken || true
        }
        const { initializeAppCheck, ReCaptchaV3Provider } =
          await import('firebase/app-check')
        initializeAppCheck(app, {
          provider: new ReCaptchaV3Provider(siteKey),
          isTokenAutoRefreshEnabled: true,
        })
      } catch (error) {
        // App Check is additive protection. A blocked script or unsupported
        // browser must not prevent local saves or Google sign-in from working.
        console.warn('Firebase App Check could not start.', error)
      }
    }

    return { auth, firestore }
  })()
  return servicesPromise
}

function accountFromUser(user: User): FirebaseAccount {
  return {
    uid: user.uid,
    displayName: sanitizeDisplayName(user.displayName),
  }
}

export async function subscribeToFirebaseAccount(
  listener: (account: FirebaseAccount | null) => void,
): Promise<() => void> {
  const [{ auth }, { onAuthStateChanged }] = await Promise.all([
    loadServices(),
    import('firebase/auth'),
  ])
  return onAuthStateChanged(auth, (user) => {
    listener(user === null ? null : accountFromUser(user))
  })
}

export async function signInWithGoogle(): Promise<void> {
  const [{ auth }, { GoogleAuthProvider, signInWithPopup }] = await Promise.all(
    [loadServices(), import('firebase/auth')],
  )
  const provider = new GoogleAuthProvider()
  provider.setCustomParameters({ prompt: 'select_account' })
  await signInWithPopup(auth, provider)
}

export async function signOutFirebase(): Promise<void> {
  const [{ auth }, { signOut }] = await Promise.all([
    loadServices(),
    import('firebase/auth'),
  ])
  await signOut(auth)
}

function timestampMillis(value: unknown): number {
  if (
    typeof value === 'object' &&
    value !== null &&
    'toMillis' in value &&
    typeof value.toMillis === 'function'
  ) {
    return value.toMillis()
  }
  return 0
}

function readCloudSnapshotData(value: unknown): CloudSaveSnapshot | null {
  if (typeof value !== 'object' || value === null) return null
  const data = value as Record<string, unknown>
  if (
    data.schemaVersion !== CLOUD_SCHEMA_VERSION ||
    typeof data.savePayload !== 'string' ||
    typeof data.recordsPayload !== 'string' ||
    typeof data.revision !== 'number' ||
    !Number.isInteger(data.revision) ||
    data.revision < 1
  ) {
    return null
  }
  return {
    schemaVersion: CLOUD_SCHEMA_VERSION,
    savePayload: data.savePayload,
    recordsPayload: data.recordsPayload,
    revision: data.revision,
    updatedAt: timestampMillis(data.updatedAt),
  }
}

export async function readCloudSave(
  uid: string,
): Promise<CloudSaveSnapshot | null> {
  const [{ firestore }, { doc, getDoc }] = await Promise.all([
    loadServices(),
    import('firebase/firestore'),
  ])
  const snapshot = await getDoc(doc(firestore, 'cloudSaves', uid))
  return snapshot.exists() ? readCloudSnapshotData(snapshot.data()) : null
}

export class CloudRevisionConflictError extends Error {
  constructor(readonly latest: CloudSaveSnapshot | null) {
    super('The cloud save changed on another device.')
    this.name = 'CloudRevisionConflictError'
  }
}

export async function writeCloudSave(
  uid: string,
  expectedRevision: number,
  payload: CloudSavePayload,
): Promise<number> {
  const [{ firestore }, { doc, runTransaction, serverTimestamp }] =
    await Promise.all([loadServices(), import('firebase/firestore')])
  const reference = doc(firestore, 'cloudSaves', uid)
  const revision = expectedRevision + 1
  await runTransaction(firestore, async (transaction) => {
    const currentDocument = await transaction.get(reference)
    const current = currentDocument.exists()
      ? readCloudSnapshotData(currentDocument.data())
      : null
    if ((current?.revision ?? 0) !== expectedRevision) {
      throw new CloudRevisionConflictError(current)
    }
    transaction.set(reference, {
      ...payload,
      revision,
      updatedAt: serverTimestamp(),
    })
  })
  return revision
}

function readLeaderboardData(
  uid: string,
  value: unknown,
): GlobalLeaderboardEntry | null {
  if (typeof value !== 'object' || value === null) return null
  const data = value as Record<string, unknown>
  if (
    typeof data.displayName !== 'string' ||
    typeof data.survivalSeconds !== 'number' ||
    typeof data.score !== 'number' ||
    typeof data.bossKills !== 'number' ||
    typeof data.level !== 'number' ||
    typeof data.difficulty !== 'number'
  ) {
    return null
  }
  return {
    uid,
    displayName: sanitizeDisplayName(data.displayName),
    survivalSeconds: Math.max(0, data.survivalSeconds),
    score: Math.max(0, data.score),
    bossKills: Math.max(0, data.bossKills),
    level: Math.max(1, data.level),
    difficulty: Math.max(1, Math.min(5, data.difficulty)),
    updatedAt: timestampMillis(data.updatedAt),
  }
}

export async function readGlobalLeaderboard(): Promise<
  readonly GlobalLeaderboardEntry[]
> {
  try {
    const cached = window.sessionStorage.getItem(LEADERBOARD_CACHE_KEY)
    if (cached !== null) {
      const parsed: unknown = JSON.parse(cached)
      if (Array.isArray(parsed)) return parsed as GlobalLeaderboardEntry[]
    }
  } catch {
    // Continue to the network when session storage is unavailable.
  }

  const [{ firestore }, { collection, getDocs, limit, orderBy, query }] =
    await Promise.all([loadServices(), import('firebase/firestore')])
  const snapshot = await getDocs(
    query(
      collection(firestore, 'leaderboard'),
      orderBy('survivalSeconds', 'desc'),
      orderBy('score', 'desc'),
      limit(10),
    ),
  )
  const entries = snapshot.docs
    .map((document) => readLeaderboardData(document.id, document.data()))
    .filter((entry): entry is GlobalLeaderboardEntry => entry !== null)
  try {
    window.sessionStorage.setItem(
      LEADERBOARD_CACHE_KEY,
      JSON.stringify(entries),
    )
  } catch {
    // The fetched list still renders for this session.
  }
  return entries
}

export async function submitLeaderboardBest(
  account: FirebaseAccount,
  record: RunRecord,
): Promise<boolean> {
  const [{ firestore }, { doc, runTransaction, serverTimestamp }] =
    await Promise.all([loadServices(), import('firebase/firestore')])
  const reference = doc(firestore, 'leaderboard', account.uid)
  let improved = false
  await runTransaction(firestore, async (transaction) => {
    const snapshot = await transaction.get(reference)
    const current = snapshot.exists()
      ? readLeaderboardData(account.uid, snapshot.data())
      : null
    const candidate = {
      survivalSeconds: Math.max(0, record.survivalSeconds ?? 0),
      score: Math.max(0, Math.floor(record.score)),
    }
    if (!isLeaderboardImprovement(candidate, current)) return
    improved = true
    transaction.set(reference, {
      displayName: account.displayName,
      survivalSeconds: candidate.survivalSeconds,
      score: candidate.score,
      bossKills: Math.max(0, record.bossKills ?? 0),
      level: Math.max(1, record.level ?? 1),
      difficulty: record.difficulty,
      updatedAt: serverTimestamp(),
    })
  })
  if (improved) {
    try {
      window.sessionStorage.removeItem(LEADERBOARD_CACHE_KEY)
    } catch {
      // Cache invalidation is an optimization only.
    }
  }
  return improved
}
