import { useId, type CSSProperties } from 'react'

import { clamp, cx } from '../utils'
import { GameButton } from './GameButton'

export interface LoadingStateProps {
  progress?: number
  label?: string
  detail?: string
  transferredBytes?: number
  totalBytes?: number
  stages?: readonly LoadingStageViewModel[]
  titleArtSrc?: string
  compact?: boolean
  /** Escape hatch so a stalled load is never a dead end. */
  onReturnToTitle?: () => void
  returnLabel?: string
}

export type LoadingStageStatus = 'pending' | 'active' | 'complete' | 'warning'

export interface LoadingStageViewModel {
  id: string
  label: string
  status: LoadingStageStatus
  detail?: string
}

export function LoadingState({
  progress,
  label = '어둠을 밝히는 중',
  detail = '잠시만 기다려 주세요.',
  transferredBytes,
  totalBytes,
  stages = [],
  titleArtSrc,
  compact = false,
  onReturnToTitle,
  returnLabel = '타이틀로 돌아가기',
}: LoadingStateProps) {
  const knownProgress = Number.isFinite(progress)
  const percent = knownProgress
    ? Math.round(clamp(progress ?? 0, 0, 1) * 100)
    : 0
  const style = { '--stillseen-progress': `${percent}%` } as CSSProperties
  const hasTransfer =
    Number.isFinite(transferredBytes) &&
    Number.isFinite(totalBytes) &&
    (totalBytes ?? 0) > 0
  const formatMegabytes = (bytes: number) =>
    `${(bytes / 1_048_576).toFixed(bytes >= 10_485_760 ? 0 : 1)} MB`

  return (
    <main
      className={cx(
        'stillseen-ui stillseen-system-state stillseen-loading-state',
        compact && 'stillseen-loading-state--compact',
      )}
      role="status"
      aria-live="polite"
      aria-busy="true"
      data-testid="loading-state"
    >
      {titleArtSrc ? (
        <img
          className="stillseen-loading-state__art"
          src={titleArtSrc}
          alt=""
          aria-hidden="true"
          draggable={false}
        />
      ) : null}
      <div className="stillseen-loading-state__veil" aria-hidden="true" />
      {/*
        Same card the static shell in index.html paints before this component
        exists. Without it the hand-off from shell to React visibly resized the
        panel and the progress bar. The geometry contract lives on
        `.stillseen-system-state__panel`.
      */}
      <div className="stillseen-system-state__panel">
        <div className="stillseen-loader" aria-hidden="true">
          <span />
          <i />
        </div>
        <h1>{label}</h1>
        <p>{detail}</p>
        <div
          className="stillseen-system-state__progress"
          data-indeterminate={!knownProgress}
          role="progressbar"
          aria-label="게임 로딩 진행률"
          aria-valuemin={knownProgress ? 0 : undefined}
          aria-valuemax={knownProgress ? 100 : undefined}
          aria-valuenow={knownProgress ? percent : undefined}
        >
          <span style={style} />
        </div>
        {knownProgress ? (
          <output className="stillseen-system-state__percent">
            {percent}%
          </output>
        ) : null}
        {hasTransfer ? (
          <output className="stillseen-system-state__transfer">
            {formatMegabytes(Math.min(transferredBytes!, totalBytes!))} /{' '}
            {formatMegabytes(totalBytes!)}
          </output>
        ) : null}
        {stages.length > 0 ? (
          <ol className="stillseen-loading-stages" aria-label="준비 단계">
            {stages.map((stage) => (
              <li
                key={stage.id}
                data-status={stage.status}
                aria-current={stage.status === 'active' ? 'step' : undefined}
              >
                <i aria-hidden="true">
                  {/* Filled circle rather than a check mark: U+2713 is in no
                      Pretendard subset and rendered from the system font. */}
                  {stage.status === 'complete'
                    ? '●'
                    : stage.status === 'warning'
                      ? '!'
                      : '·'}
                </i>
                <span>{stage.label}</span>
                {stage.detail ? <small>{stage.detail}</small> : null}
              </li>
            ))}
          </ol>
        ) : null}
        {onReturnToTitle ? (
          <div className="stillseen-overlay__actions">
            <GameButton
              variant="ghost"
              onClick={onReturnToTitle}
              testId="loading-return-to-title"
            >
              {returnLabel}
            </GameButton>
          </div>
        ) : null}
      </div>
    </main>
  )
}

export interface ErrorStateProps {
  title?: string
  message: string
  errorCode?: string
  onRetry?: () => void
  onReturnToTitle?: () => void
  retryLabel?: string
  returnLabel?: string
  busy?: boolean
  titleArtSrc?: string
}

export function ErrorState({
  title = '임무를 불러오지 못했습니다',
  message,
  errorCode,
  onRetry,
  onReturnToTitle,
  retryLabel = '다시 시도',
  returnLabel = '타이틀로 돌아가기',
  busy = false,
  titleArtSrc,
}: ErrorStateProps) {
  return (
    <main
      className="stillseen-ui stillseen-system-state stillseen-system-state--error"
      role="alert"
      data-testid="error-state"
      aria-busy={busy}
    >
      {titleArtSrc ? (
        <img
          className="stillseen-loading-state__art"
          src={titleArtSrc}
          alt=""
          aria-hidden="true"
          draggable={false}
        />
      ) : null}
      <div className="stillseen-loading-state__veil" aria-hidden="true" />
      <div className="stillseen-system-state__error-mark" aria-hidden="true">
        !
      </div>
      <p className="stillseen-eyebrow">A RIFT HAS OPENED</p>
      <h1>{title}</h1>
      <p>{message}</p>
      {errorCode ? <code>오류 코드: {errorCode}</code> : null}
      <div className="stillseen-overlay__actions stillseen-overlay__actions--row">
        {onRetry ? (
          <GameButton
            variant="primary"
            onClick={onRetry}
            autoFocus
            disabled={busy}
            testId="retry-button"
          >
            {busy ? '다시 준비하는 중…' : retryLabel}
          </GameButton>
        ) : null}
        {onReturnToTitle ? (
          <GameButton
            variant="ghost"
            onClick={onReturnToTitle}
            disabled={busy}
            testId="error-title-button"
          >
            {returnLabel}
          </GameButton>
        ) : null}
      </div>
    </main>
  )
}

export interface GameSettings {
  masterVolume: number
  musicVolume: number
  sfxVolume: number
  visionAssistIntensity: number
  reducedMotion: boolean
  gamepadVibration: boolean
}

export interface SettingsPanelProps {
  value: GameSettings
  onChange: (value: GameSettings) => void
  onClose?: () => void
  onReset?: () => void
  title?: string
  description?: string
  disabled?: boolean
  className?: string
}

export function SettingsPanel({
  value,
  onChange,
  onClose,
  onReset,
  title = '설정',
  description = '소리와 움직임 효과를 플레이 환경에 맞게 조절하세요.',
  disabled = false,
  className,
}: SettingsPanelProps) {
  const titleId = useId()
  const volumeId = useId()
  const musicVolumeId = useId()
  const sfxVolumeId = useId()
  const motionId = useId()
  const visionId = useId()
  const vibrationId = useId()
  const volume = clamp(value.masterVolume, 0, 1)
  const musicVolume = clamp(value.musicVolume, 0, 1)
  const sfxVolume = clamp(value.sfxVolume, 0, 1)

  return (
    <section
      className={cx('stillseen-ui stillseen-settings', className)}
      aria-labelledby={titleId}
      data-testid="settings-panel"
      data-reduced-motion={value.reducedMotion}
    >
      <header className="stillseen-settings__header">
        <div>
          <p className="stillseen-eyebrow">OPTIONS</p>
          <h2 id={titleId}>{title}</h2>
          <p>{description}</p>
        </div>
        {onClose ? (
          <button
            type="button"
            className="stillseen-icon-button"
            onClick={onClose}
            autoFocus
            aria-label="설정 닫기"
            data-testid="close-settings-button"
          >
            <span aria-hidden="true">×</span>
          </button>
        ) : null}
      </header>

      <fieldset className="stillseen-settings__group" disabled={disabled}>
        <legend className="stillseen-settings__legend">
          <span className="stillseen-eyebrow">AUDIO</span> 소리
        </legend>

        <label className="stillseen-setting" htmlFor={volumeId}>
          <span className="stillseen-setting__copy">
            <strong>전체 음량</strong>
            <small>음악과 효과음의 전체 크기</small>
          </span>
          <output htmlFor={volumeId}>{Math.round(volume * 100)}%</output>
          <input
            id={volumeId}
            type="range"
            min={0}
            max={1}
            step={0.05}
            value={volume}
            aria-valuetext={`${Math.round(volume * 100)}퍼센트`}
            onChange={(event) =>
              onChange({
                ...value,
                masterVolume: Number(event.currentTarget.value),
              })
            }
            data-testid="master-volume-input"
          />
        </label>

        <label className="stillseen-setting" htmlFor={musicVolumeId}>
          <span className="stillseen-setting__copy">
            <strong>음악 음량</strong>
            <small>인트로와 전투 배경음의 크기</small>
          </span>
          <output htmlFor={musicVolumeId}>
            {Math.round(musicVolume * 100)}%
          </output>
          <input
            id={musicVolumeId}
            type="range"
            min={0}
            max={1}
            step={0.05}
            value={musicVolume}
            aria-valuetext={`${Math.round(musicVolume * 100)}퍼센트`}
            onChange={(event) =>
              onChange({
                ...value,
                musicVolume: Number(event.currentTarget.value),
              })
            }
            data-testid="music-volume-input"
          />
        </label>

        <label className="stillseen-setting" htmlFor={sfxVolumeId}>
          <span className="stillseen-setting__copy">
            <strong>효과음 음량</strong>
            <small>무기, 피격, UI 효과음의 크기</small>
          </span>
          <output htmlFor={sfxVolumeId}>{Math.round(sfxVolume * 100)}%</output>
          <input
            id={sfxVolumeId}
            type="range"
            min={0}
            max={1}
            step={0.05}
            value={sfxVolume}
            aria-valuetext={`${Math.round(sfxVolume * 100)}퍼센트`}
            onChange={(event) =>
              onChange({
                ...value,
                sfxVolume: Number(event.currentTarget.value),
              })
            }
            data-testid="sfx-volume-input"
          />
        </label>
      </fieldset>

      <fieldset className="stillseen-settings__group" disabled={disabled}>
        <legend className="stillseen-settings__legend">
          <span className="stillseen-eyebrow">DISPLAY</span> 화면과 접근성
        </legend>

        <label className="stillseen-setting" htmlFor={visionId}>
          <span className="stillseen-setting__copy">
            <strong>시선 영역 강조</strong>
            <small>멈춤 영역의 색과 경계를 더 선명하게 표시합니다</small>
          </span>
          <output htmlFor={visionId}>
            {Math.round(clamp(value.visionAssistIntensity, 0, 1) * 100)}%
          </output>
          <input
            id={visionId}
            type="range"
            min={0}
            max={1}
            step={0.05}
            value={clamp(value.visionAssistIntensity, 0, 1)}
            onChange={(event) =>
              onChange({
                ...value,
                visionAssistIntensity: Number(event.currentTarget.value),
              })
            }
            data-testid="vision-assist-input"
          />
        </label>

        <label
          className="stillseen-setting stillseen-setting--toggle"
          htmlFor={motionId}
        >
          <span className="stillseen-setting__copy">
            <strong>움직임 줄이기</strong>
            <small>화면 전환, 흔들림, 반복 애니메이션을 줄입니다</small>
          </span>
          <input
            id={motionId}
            type="checkbox"
            checked={value.reducedMotion}
            onChange={(event) =>
              onChange({ ...value, reducedMotion: event.currentTarget.checked })
            }
            data-testid="reduced-motion-input"
          />
          <span className="stillseen-setting__switch" aria-hidden="true">
            <i />
          </span>
        </label>

        <label
          className="stillseen-setting stillseen-setting--toggle"
          htmlFor={vibrationId}
        >
          <span className="stillseen-setting__copy">
            <strong>컨트롤러 진동</strong>
            <small>피격과 보스 경고에 햅틱 피드백을 사용합니다</small>
          </span>
          <input
            id={vibrationId}
            type="checkbox"
            checked={value.gamepadVibration}
            onChange={(event) =>
              onChange({
                ...value,
                gamepadVibration: event.currentTarget.checked,
              })
            }
            data-testid="gamepad-vibration-input"
          />
          <span className="stillseen-setting__switch" aria-hidden="true">
            <i />
          </span>
        </label>
      </fieldset>

      {onReset ? (
        <button
          type="button"
          className="stillseen-text-button"
          onClick={onReset}
          disabled={disabled}
          data-testid="reset-settings-button"
        >
          기본값으로 되돌리기
        </button>
      ) : null}
    </section>
  )
}
