import type { CSSProperties } from 'react'

import { useGameStore } from '../runtime/gameStore'
import {
  getHitVignetteDuration,
  getHitVignetteProfile,
} from '../scene/hitVignette'

type VignetteStyle = CSSProperties & {
  '--stillseen-hit-opacity': number
  '--stillseen-hit-mid-opacity': number
  '--stillseen-hit-tail-opacity': number
  '--stillseen-hit-strength': number
  '--stillseen-hit-duration': string
  '--stillseen-hit-arc-x': string
  '--stillseen-hit-arc-y': string
  '--stillseen-hit-arc-rotation': string
}

export function DamageVignetteOverlay() {
  const hit = useGameStore((state) => state.lastPlayerHit)
  const maxHealth = useGameStore((state) => state.stats.maxHealth)
  const health = useGameStore((state) => state.health)
  const reducedMotion = useGameStore((state) => state.settings.reducedMotion)
  if (!hit) return null

  const profile = getHitVignetteProfile(
    hit.damage,
    maxHealth,
    reducedMotion,
    hit.direction,
  )
  const lethal = health <= 0
  const style: VignetteStyle = {
    '--stillseen-hit-opacity': profile.opacity,
    '--stillseen-hit-mid-opacity': profile.midOpacity,
    '--stillseen-hit-tail-opacity': profile.tailOpacity,
    '--stillseen-hit-strength': profile.strength,
    '--stillseen-hit-duration': `${getHitVignetteDuration(profile, lethal)}s`,
    '--stillseen-hit-arc-x': `${profile.arcXPercent}%`,
    '--stillseen-hit-arc-y': `${profile.arcYPercent}%`,
    '--stillseen-hit-arc-rotation': `${profile.arcRotationDegrees}deg`,
  }

  return (
    <div
      key={hit.id}
      className="stillseen-damage-vignette"
      data-testid="damage-vignette"
      data-hit-id={hit.id}
      data-lethal={lethal ? 'true' : undefined}
      style={style}
      aria-hidden="true"
    />
  )
}
