import { useId, type KeyboardEvent as ReactKeyboardEvent } from 'react'

import { trapDialogFocus } from '../focus'
import { PassiveIcon, type PassiveIconId } from './PassiveIcon'
import { WeaponIcon, type WeaponIconId } from './WeaponIcon'
import './build-ui.css'

export type LevelUpChoiceKind =
  | 'new-weapon'
  | 'weapon-upgrade'
  | 'weapon-evolution'
  | 'new-passive'
  | 'passive-upgrade'

export type LevelUpRarity = 'standard' | 'advanced' | 'prototype'

export interface LevelUpStatChange {
  readonly label: string
  readonly current: string
  readonly next: string
}

interface LevelUpChoiceBase {
  readonly id: string
  readonly kind: LevelUpChoiceKind
  readonly name: string
  readonly description: string
  readonly currentLevel: number
  readonly nextLevel: number
  readonly rarity?: LevelUpRarity
  readonly advantages: readonly string[]
  readonly drawbacks: readonly string[]
  readonly changes: readonly LevelUpStatChange[]
  readonly disabled?: boolean
}

export interface WeaponLevelUpChoice extends LevelUpChoiceBase {
  readonly kind: 'new-weapon' | 'weapon-upgrade' | 'weapon-evolution'
  readonly iconType: 'weapon'
  readonly iconId: WeaponIconId
}

export interface PassiveLevelUpChoice extends LevelUpChoiceBase {
  readonly kind: 'new-passive' | 'passive-upgrade'
  readonly iconType: 'passive'
  readonly iconId: PassiveIconId
}

export type LevelUpChoice = WeaponLevelUpChoice | PassiveLevelUpChoice

/** Level-up UI always owns exactly three offers. */
export type LevelUpChoices = readonly [
  LevelUpChoice,
  LevelUpChoice,
  LevelUpChoice,
]

export interface LevelUpOverlayProps {
  readonly level: number
  readonly choices: LevelUpChoices
  readonly onSelect: (choiceId: string) => void
  readonly rerolls?: number
  readonly onReroll?: () => void
  readonly heading?: string
  readonly description?: string
}

const KIND_LABELS: Record<LevelUpChoiceKind, string> = {
  'new-weapon': 'NEW WEAPON',
  'weapon-upgrade': 'WEAPON UPGRADE',
  'weapon-evolution': 'WEAPON EVOLUTION',
  'new-passive': 'NEW PASSIVE',
  'passive-upgrade': 'PASSIVE UPGRADE',
}

const RARITY_LABELS: Record<LevelUpRarity, string> = {
  standard: '표준',
  advanced: '고급',
  prototype: '프로토타입',
}

function ChoiceIcon({ choice }: { choice: LevelUpChoice }) {
  return choice.iconType === 'weapon' ? (
    <WeaponIcon id={choice.iconId} />
  ) : (
    <PassiveIcon id={choice.iconId} />
  )
}

/** Props-only, three-card survivor-style level-up selection. */
export function LevelUpOverlay({
  level,
  choices,
  onSelect,
  rerolls = 0,
  onReroll,
  heading = '전투 모듈을 선택하세요',
  description = '선택한 장비는 이번 런 동안 즉시 활성화됩니다.',
}: LevelUpOverlayProps) {
  const titleId = useId()
  const descriptionId = useId()
  const firstEnabledIndex = choices.findIndex((choice) => !choice.disabled)

  const select = (choice: LevelUpChoice) => {
    if (!choice.disabled) onSelect(choice.id)
  }

  const handleKeyDown = (event: ReactKeyboardEvent<HTMLElement>) => {
    const digit =
      event.code.startsWith('Digit') || event.code.startsWith('Numpad')
        ? Number(event.code.at(-1))
        : Number.NaN
    if (digit >= 1 && digit <= 3) {
      event.preventDefault()
      select(choices[digit - 1])
      return
    }
    if (event.code === 'KeyR' && onReroll && rerolls > 0) {
      event.preventDefault()
      onReroll()
      return
    }
    trapDialogFocus(event)
  }

  return (
    <section
      className="ss-level-up"
      role="dialog"
      aria-modal="true"
      aria-labelledby={titleId}
      aria-describedby={descriptionId}
      data-testid="level-up-overlay"
      onKeyDown={handleKeyDown}
    >
      <div className="ss-level-up__backdrop" aria-hidden="true" />
      <div className="ss-level-up__panel">
        <header className="ss-level-up__header">
          <p>LEVEL UP · LV {Math.max(1, Math.floor(level))}</p>
          <h2 id={titleId}>{heading}</h2>
          <span id={descriptionId}>{description}</span>
        </header>

        <div
          className="ss-level-up__choices"
          role="group"
          aria-label="레벨업 선택지 3개"
        >
          {choices.map((choice, index) => {
            const rarity = choice.rarity ?? 'standard'
            const advantages =
              choice.advantages.length > 0 ? choice.advantages : ['없음']
            const drawbacks =
              choice.drawbacks.length > 0 ? choice.drawbacks : ['없음']

            return (
              <button
                key={choice.id}
                type="button"
                className="ss-level-up-card"
                data-kind={choice.kind}
                data-rarity={rarity}
                data-testid={`level-up-choice-${choice.id}`}
                disabled={choice.disabled}
                autoFocus={index === firstEnabledIndex}
                onClick={() => select(choice)}
                aria-label={`${index + 1}번, ${choice.name}, ${KIND_LABELS[choice.kind]}, 레벨 ${choice.currentLevel}에서 ${choice.nextLevel}. ${choice.description}. 장점 ${advantages.join(', ')}. 단점 ${drawbacks.join(', ')}. ${choice.changes.map((change) => `${change.label} ${change.current}에서 ${change.next}`).join(', ')}`}
              >
                <span className="ss-level-up-card__number" aria-hidden="true">
                  {String(index + 1).padStart(2, '0')}
                </span>
                <span className="ss-level-up-card__icon" aria-hidden="true">
                  <ChoiceIcon choice={choice} />
                </span>
                <span className="ss-level-up-card__meta">
                  <small>{KIND_LABELS[choice.kind]}</small>
                  <em>{RARITY_LABELS[rarity]}</em>
                </span>
                <strong className="ss-level-up-card__name">
                  {choice.name}
                </strong>
                <span className="ss-level-up-card__level">
                  LV {Math.max(0, choice.currentLevel)}
                  <i aria-hidden="true">→</i>
                  LV {Math.max(1, choice.nextLevel)}
                </span>
                <span className="ss-level-up-card__description">
                  {choice.description}
                </span>

                <span className="ss-level-up-card__traits">
                  <span>
                    <b>장점</b>
                    <span role="list">
                      {advantages.map((advantage) => (
                        <span role="listitem" key={advantage}>
                          + {advantage}
                        </span>
                      ))}
                    </span>
                  </span>
                  <span>
                    <b>단점</b>
                    {/* En dash below, not U+2212 MINUS SIGN: the minus sign is
                        in no Pretendard subset, so it fell through to the
                        system font in the middle of a Korean sentence. */}
                    <span role="list">
                      {drawbacks.map((drawback) => (
                        <span role="listitem" key={drawback}>
                          – {drawback}
                        </span>
                      ))}
                    </span>
                  </span>
                </span>

                <span
                  className="ss-level-up-card__changes"
                  aria-label="현재 수치와 다음 수치"
                >
                  {choice.changes.map((change) => (
                    <span key={change.label}>
                      <small>{change.label}</small>
                      <span>
                        <s>{change.current}</s>
                        <i aria-hidden="true">→</i>
                        <b>{change.next}</b>
                      </span>
                    </span>
                  ))}
                </span>
                <span className="ss-level-up-card__select">
                  {choice.disabled ? '선택 불가' : `${index + 1} · 장착`}
                </span>
              </button>
            )
          })}
        </div>
        {onReroll ? (
          <footer className="ss-level-up__footer">
            <button
              type="button"
              className="ss-level-up__reroll"
              onClick={onReroll}
              disabled={rerolls <= 0}
              data-testid="level-up-reroll"
            >
              선택지 재구성 <kbd>R</kbd>
              <span>{rerolls}회 남음</span>
            </button>
          </footer>
        ) : null}
      </div>
    </section>
  )
}
