import { useId, type ReactNode } from 'react'

import { GameButton } from './GameButton'
import { OverlayShell } from './overlays'

export interface RunStat {
  label: string
  value: ReactNode
  compact?: boolean
}

export interface RunHighlight {
  label: string
  value: ReactNode
}

export interface RunResultOverlayProps {
  outcome: 'victory' | 'defeat'
  /**
   * Up to three numbers that tell the run's story at a glance. Everything
   * else belongs in `stats`, which renders as small print — the card reads
   * top-down as verdict, numbers, footnote.
   */
  highlights?: readonly RunHighlight[]
  stats?: readonly RunStat[]
  title?: string
  description?: string
  onPrimaryAction: () => void
  onReturnToTitle?: () => void
  primaryActionLabel?: string
  primaryActionDisabled?: boolean
}

export function RunResultOverlay({
  outcome,
  highlights = [],
  stats = [],
  title,
  description,
  onPrimaryAction,
  onReturnToTitle,
  primaryActionLabel,
  primaryActionDisabled = false,
}: RunResultOverlayProps) {
  const titleId = useId()
  const isVictory = outcome === 'victory'
  const resolvedTitle =
    title ?? (isVictory ? '어둠이 물러났습니다' : '게임 오버')
  const resolvedDescription =
    description ??
    (isVictory
      ? '당신은 마지막 방의 침묵을 되찾았습니다.'
      : '임무는 끝났지만, 다음 관측은 더 오래 버틸 것입니다.')

  return (
    <OverlayShell
      labelledBy={titleId}
      testId={`${outcome}-overlay`}
      tone={outcome}
      className="stillseen-result"
    >
      <div className="stillseen-result__verdict">
        <div className="stillseen-result__mark" aria-hidden="true">
          {isVictory ? '◇' : '×'}
        </div>
        <p className="stillseen-eyebrow">
          {isVictory ? 'CONTAINMENT RESTORED' : 'RUN TERMINATED'}
        </p>
        <h2 id={titleId}>{resolvedTitle}</h2>
        <p className="stillseen-overlay__copy">{resolvedDescription}</p>
        {highlights.length ? (
          <div
            className="stillseen-result__highlights"
            data-testid="run-highlights"
          >
            {highlights.slice(0, 3).map((highlight) => (
              <div key={highlight.label}>
                <strong>{highlight.value}</strong>
                <small>{highlight.label}</small>
              </div>
            ))}
          </div>
        ) : null}
        <div className="stillseen-overlay__actions stillseen-overlay__actions--row">
          <GameButton
            variant="primary"
            onClick={onPrimaryAction}
            disabled={primaryActionDisabled}
            autoFocus
            testId="result-primary-button"
          >
            {primaryActionLabel ?? (isVictory ? '새로운 임무' : '다시 도전')}
          </GameButton>
          {onReturnToTitle ? (
            <GameButton
              variant="ghost"
              onClick={onReturnToTitle}
              testId="result-title-button"
            >
              타이틀로 돌아가기
            </GameButton>
          ) : null}
        </div>
      </div>
      {stats.length ? (
        <dl className="stillseen-result__stats" data-testid="run-statistics">
          {stats.map((stat) => (
            <div
              key={stat.label}
              data-density={stat.compact ? 'compact' : undefined}
            >
              <dt>{stat.label}</dt>
              <dd
                title={typeof stat.value === 'string' ? stat.value : undefined}
              >
                {stat.value}
              </dd>
            </div>
          ))}
        </dl>
      ) : null}
    </OverlayShell>
  )
}

export type OutcomeOverlayProps = Omit<RunResultOverlayProps, 'outcome'>

/**
 * The only ending. Survival has no win condition, so there is no victory
 * variant to pair with this one — a run stops when the player does.
 */
export function DefeatOverlay(props: OutcomeOverlayProps) {
  return <RunResultOverlay {...props} outcome="defeat" />
}
