import { useCallback, useEffect, useMemo, useRef, useState } from 'react'

import type { SaveData } from '../game'
import {
  cloudPayloadFingerprint,
  createCloudSavePayload,
  parseCloudProgress,
  summarizeCloudProgress,
  type CloudProgress,
  type CloudProgressSummary,
  type CloudSaveSnapshot,
  type GlobalLeaderboardEntry,
} from './cloudData'
import {
  CloudRevisionConflictError,
  isFirebaseConfigured,
  readCloudSave,
  readGlobalLeaderboard,
  signInWithGoogle,
  signOutFirebase,
  submitLeaderboardBest,
  subscribeToFirebaseAccount,
  writeCloudSave,
  type FirebaseAccount,
} from './firebaseClient'
import { readRunRecordsUpdatedAt, type RunRecord } from './runRecords'
import { readLocalSaveUpdatedAt } from './saveStorage'

export type CloudSyncStatus =
  | 'unavailable'
  | 'guest'
  | 'connecting'
  | 'comparing'
  | 'conflict'
  | 'synced'
  | 'saving'
  | 'offline'

export interface CloudConflictViewModel {
  readonly local: CloudProgressSummary
  readonly cloud: CloudProgressSummary
  readonly recommended: 'local' | 'cloud'
}

interface PendingConflict extends CloudConflictViewModel {
  readonly cloudSnapshot: CloudSaveSnapshot
  readonly cloudProgress: CloudProgress
}

export interface UseCloudSyncOptions {
  readonly save: SaveData
  readonly runRecords: readonly RunRecord[]
  readonly initialSaveRecovered: boolean
  readonly recordsVisible: boolean
  readonly applyCloudProgress: (progress: CloudProgress) => void
}

export interface CloudSyncController {
  readonly available: boolean
  readonly account: FirebaseAccount | null
  readonly status: CloudSyncStatus
  readonly statusLabel: string
  readonly error: string | null
  readonly conflict: CloudConflictViewModel | null
  readonly globalRecords: readonly GlobalLeaderboardEntry[]
  readonly globalRecordsStatus: 'idle' | 'loading' | 'ready' | 'error'
  readonly signIn: () => Promise<void>
  readonly signOut: () => Promise<void>
  readonly chooseLocal: () => Promise<void>
  readonly chooseCloud: () => void
}

function readableError(error: unknown): string {
  if (typeof error === 'object' && error !== null && 'code' in error) {
    const code = String(error.code)
    if (code.includes('popup-closed-by-user')) return ''
    if (code.includes('network-request-failed')) {
      return '네트워크에 연결되면 다시 동기화합니다.'
    }
  }
  return 'Firebase 연결을 확인해 주세요. 로컬 저장은 계속 작동합니다.'
}

function statusLabel(status: CloudSyncStatus): string {
  switch (status) {
    case 'unavailable':
      return '로컬 저장'
    case 'guest':
      return '게스트 · 로컬 저장'
    case 'connecting':
      return 'Google 연결 중'
    case 'comparing':
      return '세이브 확인 중'
    case 'conflict':
      return '세이브 선택 필요'
    case 'saving':
      return '클라우드 저장 중'
    case 'offline':
      return '오프라인 · 로컬 저장됨'
    case 'synced':
      return '클라우드 동기화됨'
  }
}

export function useCloudSync(
  options: UseCloudSyncOptions,
): CloudSyncController {
  const {
    save,
    runRecords,
    initialSaveRecovered,
    recordsVisible,
    applyCloudProgress,
  } = options
  const available = isFirebaseConfigured()
  const saveRef = useRef(save)
  const recordsRef = useRef(runRecords)
  const applyCloudProgressRef = useRef(applyCloudProgress)
  const revisionRef = useRef(0)
  const lastSyncedFingerprint = useRef('')
  const submittedRecordKey = useRef('')
  const [account, setAccount] = useState<FirebaseAccount | null>(null)
  const [status, setStatus] = useState<CloudSyncStatus>(
    available ? 'connecting' : 'unavailable',
  )
  const [error, setError] = useState<string | null>(null)
  const [pendingConflict, setPendingConflict] =
    useState<PendingConflict | null>(null)
  const [globalRecords, setGlobalRecords] = useState<
    readonly GlobalLeaderboardEntry[]
  >([])
  const [globalRecordsStatus, setGlobalRecordsStatus] = useState<
    'idle' | 'loading' | 'ready' | 'error'
  >('idle')

  useEffect(() => {
    saveRef.current = save
    recordsRef.current = runRecords
    applyCloudProgressRef.current = applyCloudProgress
  }, [applyCloudProgress, runRecords, save])

  const openConflict = useCallback(
    (cloudSnapshot: CloudSaveSnapshot, cloudProgress: CloudProgress) => {
      const localPayload = createCloudSavePayload(
        saveRef.current,
        recordsRef.current,
      )
      const localProgress = parseCloudProgress(localPayload)
      if (localProgress === null) {
        setError('로컬 세이브를 비교할 수 없어 클라우드 적용을 중단했습니다.')
        setStatus('offline')
        return
      }
      const localUpdatedAt = Math.max(
        readLocalSaveUpdatedAt(),
        readRunRecordsUpdatedAt(),
      )
      setPendingConflict({
        local: summarizeCloudProgress(localProgress, localUpdatedAt),
        cloud: summarizeCloudProgress(cloudProgress, cloudSnapshot.updatedAt),
        recommended:
          cloudSnapshot.updatedAt > localUpdatedAt ? 'cloud' : 'local',
        cloudSnapshot,
        cloudProgress,
      })
      setStatus('conflict')
    },
    [],
  )

  const reconcile = useCallback(
    async (nextAccount: FirebaseAccount) => {
      setStatus('comparing')
      setError(null)
      try {
        const localPayload = createCloudSavePayload(
          saveRef.current,
          recordsRef.current,
        )
        const cloudSnapshot = await readCloudSave(nextAccount.uid)
        if (cloudSnapshot === null) {
          revisionRef.current = await writeCloudSave(
            nextAccount.uid,
            0,
            localPayload,
          )
          lastSyncedFingerprint.current = cloudPayloadFingerprint(localPayload)
          setStatus('synced')
          return
        }

        const cloudProgress = parseCloudProgress(cloudSnapshot)
        if (cloudProgress === null) {
          setError('클라우드 세이브가 손상되어 로컬 세이브를 유지합니다.')
          setStatus('offline')
          return
        }
        revisionRef.current = cloudSnapshot.revision
        const localFingerprint = cloudPayloadFingerprint(localPayload)
        const cloudFingerprint = cloudPayloadFingerprint(cloudSnapshot)
        if (localFingerprint === cloudFingerprint) {
          lastSyncedFingerprint.current = cloudFingerprint
          setStatus('synced')
          return
        }

        if (!initialSaveRecovered && recordsRef.current.length === 0) {
          applyCloudProgressRef.current(cloudProgress)
          lastSyncedFingerprint.current = cloudFingerprint
          setStatus('synced')
          return
        }
        openConflict(cloudSnapshot, cloudProgress)
      } catch (caught) {
        setError(readableError(caught))
        setStatus('offline')
      }
    },
    [initialSaveRecovered, openConflict],
  )

  useEffect(() => {
    if (!available) return
    let active = true
    let unsubscribe: (() => void) | undefined
    void subscribeToFirebaseAccount((nextAccount) => {
      if (!active) return
      setAccount(nextAccount)
      setPendingConflict(null)
      revisionRef.current = 0
      lastSyncedFingerprint.current = ''
      submittedRecordKey.current = ''
      setGlobalRecords([])
      setGlobalRecordsStatus('idle')
      if (nextAccount === null) {
        setStatus('guest')
        setError(null)
      } else {
        void reconcile(nextAccount)
      }
    })
      .then((cleanup) => {
        if (active) unsubscribe = cleanup
        else cleanup()
      })
      .catch((caught) => {
        if (!active) return
        setError(readableError(caught))
        setStatus('offline')
      })
    return () => {
      active = false
      unsubscribe?.()
    }
  }, [available, reconcile])

  useEffect(() => {
    if (account === null || status !== 'offline') return
    const retryWhenOnline = () => void reconcile(account)
    window.addEventListener('online', retryWhenOnline)
    return () => window.removeEventListener('online', retryWhenOnline)
  }, [account, reconcile, status])

  useEffect(() => {
    if (account === null || status !== 'synced') return
    const payload = createCloudSavePayload(save, runRecords)
    const fingerprint = cloudPayloadFingerprint(payload)
    if (fingerprint === lastSyncedFingerprint.current) return
    const timer = window.setTimeout(() => {
      setStatus('saving')
      void writeCloudSave(account.uid, revisionRef.current, payload)
        .then((revision) => {
          revisionRef.current = revision
          lastSyncedFingerprint.current = fingerprint
          setStatus('synced')
          setError(null)
        })
        .catch((caught) => {
          if (
            caught instanceof CloudRevisionConflictError &&
            caught.latest !== null
          ) {
            const cloudProgress = parseCloudProgress(caught.latest)
            if (cloudProgress !== null) {
              openConflict(caught.latest, cloudProgress)
              return
            }
          }
          setError(readableError(caught))
          setStatus('offline')
        })
    }, 3_000)
    return () => window.clearTimeout(timer)
  }, [account, openConflict, runRecords, save, status])

  useEffect(() => {
    const best = runRecords[0]
    if (account === null || status !== 'synced' || best === undefined) return
    const key = `${account.uid}:${best.at}:${best.score}`
    if (submittedRecordKey.current === key) return
    submittedRecordKey.current = key
    void submitLeaderboardBest(account, best).catch((caught) => {
      setError(readableError(caught))
    })
  }, [account, runRecords, status])

  useEffect(() => {
    if (!recordsVisible || account === null) return
    if (globalRecordsStatus !== 'idle') return
    let cancelled = false
    void Promise.resolve().then(async () => {
      if (cancelled) return
      setGlobalRecordsStatus('loading')
      try {
        const records = await readGlobalLeaderboard()
        if (cancelled) return
        setGlobalRecords(records)
        setGlobalRecordsStatus('ready')
      } catch (caught) {
        if (cancelled) return
        setError(readableError(caught))
        setGlobalRecordsStatus('error')
      }
    })
    return () => {
      cancelled = true
    }
  }, [account, globalRecordsStatus, recordsVisible])

  const signIn = useCallback(async () => {
    if (!available) return
    setStatus('connecting')
    setError(null)
    try {
      await signInWithGoogle()
    } catch (caught) {
      const message = readableError(caught)
      setError(message || null)
      setStatus('guest')
    }
  }, [available])

  const signOut = useCallback(async () => {
    try {
      await signOutFirebase()
    } catch (caught) {
      setError(readableError(caught))
    }
  }, [])

  const chooseLocal = useCallback(async () => {
    if (account === null || pendingConflict === null) return
    setStatus('saving')
    const payload = createCloudSavePayload(saveRef.current, recordsRef.current)
    try {
      revisionRef.current = await writeCloudSave(
        account.uid,
        pendingConflict.cloudSnapshot.revision,
        payload,
      )
      lastSyncedFingerprint.current = cloudPayloadFingerprint(payload)
      setPendingConflict(null)
      setError(null)
      setStatus('synced')
    } catch (caught) {
      if (
        caught instanceof CloudRevisionConflictError &&
        caught.latest !== null
      ) {
        const cloudProgress = parseCloudProgress(caught.latest)
        if (cloudProgress !== null) {
          openConflict(caught.latest, cloudProgress)
          return
        }
      }
      setError(readableError(caught))
      setStatus('offline')
    }
  }, [account, openConflict, pendingConflict])

  const chooseCloud = useCallback(() => {
    if (pendingConflict === null) return
    applyCloudProgressRef.current(pendingConflict.cloudProgress)
    revisionRef.current = pendingConflict.cloudSnapshot.revision
    lastSyncedFingerprint.current = cloudPayloadFingerprint(
      pendingConflict.cloudSnapshot,
    )
    setPendingConflict(null)
    setError(null)
    setStatus('synced')
  }, [pendingConflict])

  return useMemo(
    () => ({
      available,
      account,
      status,
      statusLabel: statusLabel(status),
      error,
      conflict: pendingConflict,
      globalRecords,
      globalRecordsStatus,
      signIn,
      signOut,
      chooseLocal,
      chooseCloud,
    }),
    [
      account,
      available,
      chooseCloud,
      chooseLocal,
      error,
      globalRecords,
      globalRecordsStatus,
      pendingConflict,
      signIn,
      signOut,
      status,
    ],
  )
}
