import type { CloudConflictViewModel } from '../runtime/useCloudSync'
import { GameButton } from './screens/GameButton'

export interface CloudSaveConflictDialogProps {
  readonly conflict: CloudConflictViewModel
  readonly onChooseLocal: () => void
  readonly onChooseCloud: () => void
}

function formatUpdatedAt(value: number): string {
  if (value <= 0) return '수정 시각 없음'
  return new Intl.DateTimeFormat('ko-KR', {
    dateStyle: 'short',
    timeStyle: 'short',
  }).format(new Date(value))
}

function SummaryCard({
  label,
  summary,
  recommended,
}: {
  readonly label: string
  readonly summary: CloudConflictViewModel['local']
  readonly recommended: boolean
}) {
  return (
    <article
      className="stillseen-cloud-conflict__card"
      data-recommended={recommended || undefined}
    >
      <header>
        <h3>{label}</h3>
        {recommended ? <span>최신 · 권장</span> : null}
      </header>
      <dl>
        <div>
          <dt>데이터 파편</dt>
          <dd>{summary.currency.toLocaleString('ko-KR')}</dd>
        </div>
        <div>
          <dt>해금</dt>
          <dd>{summary.unlockCount}</dd>
        </div>
        <div>
          <dt>영구 강화</dt>
          <dd>{summary.permanentUpgradeCount}</dd>
        </div>
        <div>
          <dt>최고 생존</dt>
          <dd>{Math.floor(summary.bestSurvivalSeconds)}초</dd>
        </div>
      </dl>
      <small>{formatUpdatedAt(summary.updatedAt)}</small>
    </article>
  )
}

export function CloudSaveConflictDialog({
  conflict,
  onChooseLocal,
  onChooseCloud,
}: CloudSaveConflictDialogProps) {
  return (
    <div className="stillseen-cloud-conflict" role="presentation">
      <section
        className="stillseen-cloud-conflict__dialog"
        role="dialog"
        aria-modal="true"
        aria-labelledby="cloud-save-conflict-title"
        data-testid="cloud-save-conflict"
      >
        <p className="stillseen-eyebrow">CLOUD SAVE CONFLICT</p>
        <h2 id="cloud-save-conflict-title">사용할 진행도를 선택하세요</h2>
        <p>
          선택하지 않은 쪽은 덮어씁니다. 볼륨·진동·모션 설정은 이 기기에 그대로
          유지됩니다.
        </p>
        <div className="stillseen-cloud-conflict__choices">
          <SummaryCard
            label="이 기기"
            summary={conflict.local}
            recommended={conflict.recommended === 'local'}
          />
          <SummaryCard
            label="클라우드"
            summary={conflict.cloud}
            recommended={conflict.recommended === 'cloud'}
          />
        </div>
        <div className="stillseen-cloud-conflict__actions">
          <GameButton
            variant={conflict.recommended === 'local' ? 'primary' : 'ghost'}
            onClick={onChooseLocal}
            testId="choose-local-save"
          >
            이 기기 사용
          </GameButton>
          <GameButton
            variant={conflict.recommended === 'cloud' ? 'primary' : 'ghost'}
            onClick={onChooseCloud}
            testId="choose-cloud-save"
          >
            클라우드 사용
          </GameButton>
        </div>
      </section>
    </div>
  )
}
