import {
  createDefaultSave,
  loadSave,
  serializeSave,
  type SaveData,
} from '../game'
import {
  compareRunRecords,
  parseRunRecords,
  type RunRecord,
} from './runRecords'

export const CLOUD_SCHEMA_VERSION = 1

export interface CloudSavePayload {
  readonly schemaVersion: typeof CLOUD_SCHEMA_VERSION
  readonly savePayload: string
  readonly recordsPayload: string
}

export interface CloudSaveSnapshot extends CloudSavePayload {
  readonly revision: number
  readonly updatedAt: number
}

export interface CloudProgress {
  readonly save: SaveData
  readonly records: readonly RunRecord[]
}

export interface CloudProgressSummary {
  readonly currency: number
  readonly unlockCount: number
  readonly permanentUpgradeCount: number
  readonly bestSurvivalSeconds: number
  readonly updatedAt: number
}

export interface GlobalLeaderboardEntry {
  readonly uid: string
  readonly displayName: string
  readonly survivalSeconds: number
  readonly score: number
  readonly bossKills: number
  readonly level: number
  readonly difficulty: number
  readonly updatedAt: number
}

export function createCloudSavePayload(
  save: SaveData,
  records: readonly RunRecord[],
): CloudSavePayload {
  // Device settings deliberately stay local. A valid default settings block
  // lets the existing save validator remain the single source of truth.
  const portableSave: SaveData = {
    ...createDefaultSave(),
    meta: save.meta,
  }
  return {
    schemaVersion: CLOUD_SCHEMA_VERSION,
    savePayload: serializeSave(portableSave),
    recordsPayload: JSON.stringify(
      [...records].sort(compareRunRecords).slice(0, 10),
    ),
  }
}

export function cloudPayloadFingerprint(payload: CloudSavePayload): string {
  return `${payload.schemaVersion}:${payload.savePayload}:${payload.recordsPayload}`
}

export function parseCloudProgress(
  snapshot: CloudSavePayload,
): CloudProgress | null {
  if (snapshot.schemaVersion !== CLOUD_SCHEMA_VERSION) return null
  const loaded = loadSave(snapshot.savePayload)
  if (loaded.status === 'reset') return null
  return {
    save: loaded.data,
    records: parseRunRecords(snapshot.recordsPayload),
  }
}

export function summarizeCloudProgress(
  progress: CloudProgress,
  updatedAt: number,
): CloudProgressSummary {
  const meta = progress.save.meta
  const permanentUpgradeCount = Object.values(meta.permanentStatLevels).reduce(
    (total, level) => total + level,
    0,
  )
  return {
    currency: meta.currency,
    unlockCount: meta.unlockedWeaponIds.length + meta.unlockedPassiveIds.length,
    permanentUpgradeCount,
    bestSurvivalSeconds: progress.records[0]?.survivalSeconds ?? 0,
    updatedAt,
  }
}

export function sanitizeDisplayName(value: string | null | undefined): string {
  const compact = value?.replace(/\s+/g, ' ').trim() ?? ''
  return (compact || '익명 생존자').slice(0, 40)
}

export function isLeaderboardImprovement(
  candidate: Pick<GlobalLeaderboardEntry, 'survivalSeconds' | 'score'>,
  current: Pick<GlobalLeaderboardEntry, 'survivalSeconds' | 'score'> | null,
): boolean {
  if (current === null) return true
  return (
    candidate.survivalSeconds > current.survivalSeconds ||
    (candidate.survivalSeconds === current.survivalSeconds &&
      candidate.score > current.score)
  )
}
