import type { ReactNode } from 'react'

import { cx } from '../utils'

export type GameButtonVariant = 'primary' | 'secondary' | 'danger' | 'ghost'

export interface GameButtonProps {
  children: ReactNode
  onClick?: () => void
  variant?: GameButtonVariant
  disabled?: boolean
  autoFocus?: boolean
  type?: 'button' | 'submit' | 'reset'
  className?: string
  testId?: string
  ariaLabel?: string
}

export function GameButton({
  children,
  onClick,
  variant = 'secondary',
  disabled = false,
  autoFocus = false,
  type = 'button',
  className,
  testId,
  ariaLabel,
}: GameButtonProps) {
  return (
    <button
      type={type}
      className={cx(
        'stillseen-button',
        `stillseen-button--${variant}`,
        className,
      )}
      onClick={onClick}
      disabled={disabled}
      autoFocus={autoFocus}
      data-testid={testId}
      aria-label={ariaLabel}
    >
      <span className="stillseen-button__edge" aria-hidden="true" />
      <span className="stillseen-button__label">{children}</span>
    </button>
  )
}
