import { useId, type ReactNode } from 'react'

import { trapDialogFocus } from '../focus'
import { cx } from '../utils'
import { GameButton } from './GameButton'

export interface OverlayShellProps {
  children: ReactNode
  labelledBy: string
  testId: string
  tone?: 'neutral' | 'victory' | 'defeat' | 'reward'
  className?: string
}

export function OverlayShell({
  children,
  labelledBy,
  testId,
  tone = 'neutral',
  className,
}: OverlayShellProps) {
  return (
    <div
      className={cx(
        'stillseen-ui stillseen-overlay',
        `stillseen-overlay--${tone}`,
        className,
      )}
      role="dialog"
      aria-modal="true"
      aria-labelledby={labelledBy}
      data-testid={testId}
      onKeyDown={trapDialogFocus}
    >
      <div className="stillseen-overlay__backdrop" aria-hidden="true" />
      <div className="stillseen-overlay__panel">{children}</div>
    </div>
  )
}

export interface PauseOverlayProps {
  onResume: () => void
  onRestart?: () => void
  onOpenSettings?: () => void
  onQuit?: () => void
}

export function PauseOverlay({
  onResume,
  onRestart,
  onOpenSettings,
  onQuit,
}: PauseOverlayProps) {
  const titleId = useId()

  return (
    <OverlayShell
      labelledBy={titleId}
      testId="pause-overlay"
      className="stillseen-pause-overlay"
    >
      <h2 id={titleId} className="stillseen-sr-only">
        일시 정지
      </h2>
      <div className="stillseen-pause">
        <GameButton
          variant="primary"
          onClick={onResume}
          autoFocus
          testId="resume-game-button"
        >
          계속하기
        </GameButton>
        {onOpenSettings ? (
          <GameButton onClick={onOpenSettings} testId="pause-settings-button">
            설정
          </GameButton>
        ) : null}
        {onRestart ? (
          <GameButton onClick={onRestart} testId="restart-run-button">
            임무 다시 시작
          </GameButton>
        ) : null}
        {onQuit ? (
          <GameButton
            variant="ghost"
            onClick={onQuit}
            testId="quit-to-title-button"
          >
            타이틀로 돌아가기
          </GameButton>
        ) : null}
      </div>
    </OverlayShell>
  )
}
