import { useEffect, useRef } from 'react'
import {
  DAMAGE_POPUP_POOL_SIZE,
  attachDamagePopupLayer,
  detachDamagePopupLayer,
} from '../scene/damagePopups'
import './damage-popup-hud.css'

/**
 * Fixed span pool for floating damage numbers. The scene loop writes
 * transforms straight to these nodes; React renders this exactly once per
 * mount and never again.
 */
export function DamagePopupHud() {
  const containerRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    if (containerRef.current) attachDamagePopupLayer(containerRef.current)
    return () => detachDamagePopupLayer()
  }, [])

  return (
    <div
      ref={containerRef}
      className="ss-damage-popups"
      data-testid="damage-popup-layer"
      aria-hidden="true"
    >
      {Array.from({ length: DAMAGE_POPUP_POOL_SIZE }, (_, index) => (
        <span key={index} className="ss-damage-popup" data-visible="false" />
      ))}
    </div>
  )
}
