import {
  createDefaultSave,
  loadSave,
  serializeSave,
  type SaveData,
} from '../game'

const SAVE_KEY = 'stillseen.save.v8'
const SAVE_UPDATED_AT_KEY = 'stillseen.save.updated.v1'
const PREVIOUS_SAVE_KEYS = [
  'stillseen.save.v7',
  'stillseen.save.v6',
  'stillseen.save.v5',
  'stillseen.save.v4',
  'stillseen.save.v3',
  'stillseen.save.v2',
  'stillseen.save.v1',
] as const
const LEGACY_SAVE_KEYS = [
  'boda.save.v5',
  'boda.save.v4',
  'boda.save.v3',
  'boda.save.v2',
  'boda.save.v1',
] as const
const QUARANTINE_KEY_PREFIX = 'stillseen.save.quarantine.'
const VISION_ASSIST_KEY = 'stillseen.vision-assist.v1'
const LEGACY_VISION_ASSIST_KEY = 'boda.vision-assist.v1'
const ARENA_KEY = 'stillseen.arena.v1'

export interface LocalSaveLoad {
  readonly data: SaveData
  /** True when a stored key produced a usable save rather than a fresh default. */
  readonly recovered: boolean
}

/**
 * Preserves bytes that were present but could not be read — a save written by
 * a newer build, or one damaged in storage. The quarantine key is stable per
 * source key rather than timestamped, so a machine that cannot write back to
 * SAVE_KEY re-quarantines the same slot instead of growing a new entry on
 * every reload.
 */
function quarantineRawSave(key: string, raw: string): void {
  try {
    window.localStorage.setItem(`${QUARANTINE_KEY_PREFIX}${key}`, raw)
  } catch {
    // Storage may be full or disabled; the source key is left untouched.
  }
}

export function readLocalSave(): LocalSaveLoad {
  try {
    for (const key of [SAVE_KEY, ...PREVIOUS_SAVE_KEYS, ...LEGACY_SAVE_KEYS]) {
      const raw = window.localStorage.getItem(key)
      if (raw === null) continue
      const loaded = loadSave(raw)
      if (loaded.status !== 'reset')
        return { data: loaded.data, recovered: true }
      if (raw.trim() !== '') quarantineRawSave(key, raw)
    }
    return { data: createDefaultSave(), recovered: false }
  } catch {
    return { data: createDefaultSave(), recovered: false }
  }
}

export function removeMigratedSaveKeys(): void {
  try {
    for (const key of [...PREVIOUS_SAVE_KEYS, ...LEGACY_SAVE_KEYS]) {
      window.localStorage.removeItem(key)
    }
  } catch {
    // Reaching window.localStorage at all throws in a sandboxed frame, so the
    // guard belongs here rather than in each caller — every other export in
    // this module already defends itself.
  }
}

export function writeLocalSave(save: SaveData): boolean {
  try {
    const serialized = serializeSave(save)
    if (window.localStorage.getItem(SAVE_KEY) !== serialized) {
      window.localStorage.setItem(SAVE_KEY, serialized)
      window.localStorage.setItem(SAVE_UPDATED_AT_KEY, String(Date.now()))
    } else if (window.localStorage.getItem(SAVE_UPDATED_AT_KEY) === null) {
      window.localStorage.setItem(SAVE_UPDATED_AT_KEY, String(Date.now()))
    }
    return true
  } catch {
    // Storage may be disabled; gameplay remains available for this session.
    return false
  }
}

export function readLocalSaveUpdatedAt(): number {
  try {
    const value = Number(window.localStorage.getItem(SAVE_UPDATED_AT_KEY))
    return Number.isFinite(value) && value > 0 ? value : 0
  } catch {
    return 0
  }
}

export function readVisionAssist(): number | null {
  try {
    const raw =
      window.localStorage.getItem(VISION_ASSIST_KEY) ??
      window.localStorage.getItem(LEGACY_VISION_ASSIST_KEY)
    if (raw === null || raw.trim() === '') return null
    const value = Number(raw)
    return Number.isFinite(value) && value >= 0 && value <= 1 ? value : null
  } catch {
    return null
  }
}

export function writeVisionAssist(value: number): void {
  try {
    window.localStorage.setItem(VISION_ASSIST_KEY, String(value))
  } catch {
    // Storage may be disabled; keep the setting for this session.
  }
}

/**
 * The lobby's chosen survival arena.
 *
 * Deliberately a sibling key rather than a field on the save. `MetaProgression`
 * is rebuilt field by field in `copyCurrentSave`, so a new key there means
 * three edits on the save validation surface that every existing save has to
 * clear — a large risk for a cosmetic preference. Storage stays dumb: the
 * caller validates the id against the arena list it actually offers.
 */
export function readSelectedArena(): string | null {
  try {
    const raw = window.localStorage.getItem(ARENA_KEY)
    return raw === null || raw.trim() === '' ? null : raw
  } catch {
    return null
  }
}

export function writeSelectedArena(value: string): void {
  try {
    window.localStorage.setItem(ARENA_KEY, value)
  } catch {
    // Storage may be disabled; keep the selection for this session.
  }
}
