import { useId, type SVGProps } from 'react'

import { cx } from '../utils'

export type PassiveIconId =
  | 'armor'
  | 'regeneration'
  | 'damage'
  | 'haste'
  | 'range'
  | 'magnet'
  | 'speed'
  | 'critical'
  | 'optic-reach'
  | 'optic-spread'
  | 'generic'

export interface PassiveIconProps extends Omit<
  SVGProps<SVGSVGElement>,
  'children'
> {
  id: PassiveIconId
  title?: string
}

/** Monochrome, `currentColor` passive-item glyph library. */
export function PassiveIcon({
  id,
  title,
  className,
  ...svgProps
}: PassiveIconProps) {
  const titleId = useId()
  const stroke = {
    fill: 'none',
    stroke: 'currentColor',
    strokeWidth: 3.25,
    strokeLinecap: 'round' as const,
    strokeLinejoin: 'round' as const,
  }

  const glyph = (() => {
    switch (id) {
      case 'armor':
        return (
          <>
            <path
              {...stroke}
              d="m32 7 20 8v15c0 13-8 22-20 27C20 52 12 43 12 30V15l20-8Z"
            />
            <path {...stroke} d="M32 15v33M20 24h24" />
          </>
        )
      case 'regeneration':
        return (
          <>
            <path
              {...stroke}
              d="M32 56 14 39C2 27 10 12 21 14c6 1 9 5 11 10 2-5 5-9 11-10 11-2 19 13 7 25L32 56Z"
            />
            <path {...stroke} d="M32 25v18M23 34h18" />
          </>
        )
      case 'damage':
        return (
          <>
            <path
              {...stroke}
              d="m32 6 6 17 18 1-14 11 5 18-15-10-15 10 5-18L8 24l18-1 6-17Z"
            />
            <circle cx="32" cy="32" r="4" fill="currentColor" />
          </>
        )
      case 'haste':
        return (
          <>
            <circle {...stroke} cx="32" cy="34" r="20" />
            <path {...stroke} d="M32 18v17l11 6M24 7h16M49 15l5 5" />
          </>
        )
      case 'range':
        return (
          <>
            <circle {...stroke} cx="32" cy="32" r="22" />
            <circle {...stroke} cx="32" cy="32" r="12" />
            <circle cx="32" cy="32" r="4" fill="currentColor" />
            <path {...stroke} d="M32 5v8m0 38v8M5 32h8m38 0h8" />
          </>
        )
      case 'magnet':
        return (
          <>
            <path
              {...stroke}
              d="M14 11v25c0 13 8 21 18 21s18-8 18-21V11H39v25c0 6-3 10-7 10s-7-4-7-10V11H14Z"
            />
            <path {...stroke} d="M14 20h11m14 0h11" />
          </>
        )
      case 'speed':
        return (
          <>
            <path
              {...stroke}
              d="M10 44h34c9 0 13-6 10-13l-5-11-9 13H25L14 25 8 35l2 9Z"
            />
            <path {...stroke} d="M7 50h36M5 18h20M10 11h20" />
          </>
        )
      case 'critical':
        return (
          <>
            <circle {...stroke} cx="32" cy="32" r="21" />
            <path
              {...stroke}
              d="m32 14 5 12 13 1-10 8 3 13-11-7-11 7 3-13-10-8 13-1 5-12Z"
            />
          </>
        )
      // The two optic glyphs are the same cone read at different widths, so
      // reach and spread are legible against each other at HUD size.
      case 'optic-reach':
        return (
          <>
            <path {...stroke} d="M32 54 20 12h24L32 54Z" />
            <path {...stroke} d="M32 24v22" />
          </>
        )
      case 'optic-spread':
        return (
          <>
            <path {...stroke} d="M32 54 6 18h52L32 54Z" />
            <path {...stroke} d="M18 30h28" />
          </>
        )
      default:
        return (
          <>
            <path {...stroke} d="m32 7 23 25-23 25L9 32 32 7Z" />
            <circle {...stroke} cx="32" cy="32" r="7" />
          </>
        )
    }
  })()

  return (
    <svg
      {...svgProps}
      className={cx('ss-build-icon ss-build-icon--passive', className)}
      viewBox="0 0 64 64"
      role={title ? 'img' : undefined}
      aria-hidden={title ? undefined : true}
      aria-labelledby={title ? titleId : undefined}
      focusable="false"
      data-passive-icon={id}
    >
      {title ? <title id={titleId}>{title}</title> : null}
      {glyph}
    </svg>
  )
}
