export function encounterBannerViewModel(
  event: EncounterPresentationEvent,
): EncounterBannerViewModel {
  if (event.endless) {
    return {
      id: event.id,
      kind: event.kind,
      endless: true,
      chamber: event.chamber,
      title: '무한 생존 프로토콜',
      subtitle: '선택한 자동 무기로 출격 · XP 코어를 회수해 빌드를 완성하세요',
      boss: false,
      badges: ['05:00 보스 신호', '20분 이후 계속 진행'],
    }
  }

  const badges =
    event.kind === 'start'
      ? [
          ENCOUNTER_RISK_LABELS[event.risk],
          event.mutationId ? MUTATION_LABELS[event.mutationId] : undefined,
          event.eliteCount > 0 ? `정예 ${event.eliteCount}` : undefined,
        ].filter((label): label is string => label !== undefined)
      : []

  return {
    id: event.id,
    kind: event.kind,
    chamber: event.chamber,
    title: event.roomName,
    subtitle:
      event.kind === 'start'
        ? event.boss
          ? '마지막 존재를 처치하세요'
          : '탈출구에 도달하세요 · 처치는 선택, 파편은 가산'
        : event.boss
          ? '정화 완료 · 다음 섹터가 열립니다'
          : '탈출 성공 · 다음 섹터가 열립니다',
    boss: event.boss,
    badges,
  }
}

