export function bootStageViewModels(
  progress: BootProgress,
  warnings: readonly BootWarning[],
): readonly LoadingStageViewModel[] {
  const activeIndex = BOOT_STAGE_ORDER.indexOf(progress.stage)
  const warningStages = new Set(warnings.map((warning) => warning.stage))
  return BOOT_STAGE_ORDER.map((stage, index) => ({
    id: stage,
    label: BOOT_STAGE_LABELS[stage],
    status: warningStages.has(stage)
      ? 'warning'
      : index < activeIndex || progress.progress >= 1
        ? 'complete'
        : index === activeIndex
          ? 'active'
          : 'pending',
    detail:
      stage === progress.stage
        ? progress.detail
        : warnings.find((warning) => warning.stage === stage)?.message,
  }))
}

export function describePermanentEffect(
  id: PermanentStatId,
  level: number,
): string {
  if (id === 'vitality') return `기존 투자 전환 · 관측 각도 +${level * 4}°`
  if (id === 'power') return `기본 공격력 +${level * 5}%`
  if (id === 'mobility') return `기본 이동 속도 +${level * 2}%`
  return `관측 거리 +${(level * 0.35).toFixed(2)} · 각도 +${level * 4}°`
}

export function defaultSeed(): string {
  const querySeed = new URLSearchParams(window.location.search).get('seed')
  if (querySeed?.trim()) return querySeed.trim().slice(0, 40)
  return `STILLSEEN-${new Date().toISOString().slice(0, 10).replaceAll('-', '')}`
}
