/** @deprecated Retained for API compatibility; not used by LobbyScreen. */
export interface PermanentUpgradePanelProps {
  upgrades: readonly PermanentUpgradeViewModel[]
  currency: number
  onPurchase: (upgradeId: string) => void
  busy?: boolean
}

export function PermanentUpgradePanel({
  upgrades,
  currency,
  onPurchase,
  busy = false,
}: PermanentUpgradePanelProps) {
  const safeCurrency = Number.isFinite(currency)
    ? Math.max(0, Math.floor(currency))
    : 0
  return (
    <section
      className="stillseen-permanent-upgrades"
      aria-label="영구 능력 강화"
    >
      {upgrades.map((upgrade) => {
        const maximum = Math.max(1, Math.floor(upgrade.maxLevel))
        const level = clamp(Math.floor(upgrade.level), 0, maximum)
        const cost = upgrade.cost === null ? null : Math.max(0, upgrade.cost)
        const disabled =
          busy ||
          upgrade.locked ||
          level >= maximum ||
          cost === null ||
          safeCurrency < cost
        return (
          <article
            key={upgrade.id}
            className="stillseen-permanent-upgrade"
            data-testid={`permanent-upgrade-${upgrade.id}`}
          >
            <h3>{upgrade.name}</h3>
            <p>{upgrade.description}</p>
            <GameButton
              disabled={disabled}
              onClick={() => onPurchase(upgrade.id)}
              testId={`purchase-permanent-upgrade-${upgrade.id}`}
            >
              {level >= maximum ? '최대 단계' : `강화 · ${cost ?? 0}`}
            </GameButton>
          </article>
        )
      })}
    </section>
  )
}

function ContentUnlockCard({
  content,
  currency,
  busy,
  onUnlock,
}: {
  readonly content: ContentUnlockViewModel
  readonly currency: number
  readonly busy: boolean
  readonly onUnlock?: (contentId: string) => void
}) {
  const cost = Math.max(0, Math.floor(content.cost))
  const affordable = currency >= cost
  const disabled = busy || content.unlocked || !affordable || !onUnlock
  const categoryLabel = content.category === 'weapon' ? '자동 무기' : '패시브'

  return (
    <article
      className="ss-lobby-unlock-card"
      data-category={content.category}
      data-unlocked={content.unlocked}
      data-testid={`content-unlock-${content.id}`}
    >
      <header>
        <span>{categoryLabel}</span>
        <small>{content.unlocked ? 'UNLOCKED' : 'LOCKED'}</small>
      </header>
      <h3>{content.name}</h3>
      <p>{content.description}</p>
      <dl>
        <div data-trait="positive">
          <dt>장점</dt>
          <dd>{content.positive}</dd>
        </div>
        <div data-trait="negative">
          <dt>단점</dt>
          <dd>{content.negative}</dd>
        </div>
      </dl>
      <GameButton
        variant={content.unlocked ? 'secondary' : 'primary'}
        disabled={disabled}
        onClick={() => onUnlock?.(content.id)}
        testId={`unlock-content-${content.id}`}
        ariaLabel={`${content.name} ${content.unlocked ? '해금 완료' : '해금'}`}
      >
        {content.unlocked
          ? '해금 완료'
          : affordable
            ? `해금 · ${cost.toLocaleString('ko-KR')}`
            : `파편 부족 · ${cost.toLocaleString('ko-KR')}`}
      </GameButton>
    </article>
  )
}

/**
 * One permanent stat, as a track of five pips plus its next purchase.
 *
 * Deliberately not the retired `PermanentUpgradePanel` below: that one is built
 * on the pre-survival lobby's markup and stylesheet, both of which are being
 * removed. This is the same shape as `ContentUnlockCard` so the augment tab
 * reads as one screen rather than two eras of it.
 */
function PermanentStatCard({
  upgrade,
  currency,
  busy,
  onPurchase,
}: {
  readonly upgrade: PermanentUpgradeViewModel
  readonly currency: number
  readonly busy: boolean
  readonly onPurchase?: (upgradeId: string) => void
}) {
  const maximum = Math.max(1, Math.floor(upgrade.maxLevel))
  const level = clamp(Math.floor(upgrade.level), 0, maximum)
  const maxed = level >= maximum
  const cost = upgrade.cost === null ? null : Math.max(0, upgrade.cost)
  const affordable = cost !== null && currency >= cost
  const disabled = busy || upgrade.locked || maxed || !affordable || !onPurchase

  return (
    <article
      className="ss-lobby-stat-card"
      data-maxed={maxed}
      data-testid={`permanent-stat-${upgrade.id}`}
    >
      <header>
        <span aria-hidden="true">{upgrade.iconLabel}</span>
        <small>
          {level} / {maximum}
        </small>
      </header>
      <h3>{upgrade.name}</h3>
      <p>{upgrade.description}</p>
      <ol
        className="ss-lobby-stat-track"
        aria-label={`${upgrade.name} ${maximum}단계 중 ${level}단계`}
      >
        {Array.from({ length: maximum }, (_, index) => (
          <li key={index} data-filled={index < level} />
        ))}
      </ol>
      <p className="ss-lobby-stat-effect">
        {upgrade.currentEffect}
        {upgrade.nextEffect ? <span> → {upgrade.nextEffect}</span> : null}
      </p>
      <GameButton
        variant={maxed ? 'secondary' : 'primary'}
        disabled={disabled}
        onClick={() => onPurchase?.(upgrade.id)}
        testId={`purchase-permanent-stat-${upgrade.id}`}
        ariaLabel={`${upgrade.name} ${maxed ? '최대 단계' : '강화'}`}
      >
        {maxed
          ? '최대 단계'
          : affordable
            ? `강화 · ${(cost ?? 0).toLocaleString('ko-KR')}`
            : `파편 부족 · ${(cost ?? 0).toLocaleString('ko-KR')}`}
      </GameButton>
    </article>
  )
}

export function LobbyScreen(props: LobbyScreenProps) {
  const {
    activeTab,
    onTabChange,
    runRecords = [],
    globalRunRecords = [],
    globalRecordsStatus = 'idle',
    cloudAccount,
    currency,
    seed,
    onSeedChange,
    preview,
    contentUnlocks = [],
    onUnlockContent,
    permanentUpgrades = [],
    onPurchasePermanentUpgrade,
    arsenalWeapons = [],
    arenaOptions = [],
    selectedArenaId,
    onArenaSelect,
    difficultyOptions = [],
    selectedDifficulty,
    onDifficultySelect,
    tutorialEnabled = false,
    onTutorialEnabledChange,
    onStart,
    onOpenSettings,
    announcement = '',
    credits = [],
    creditsHref = DEFAULT_CREDITS_HREF,
    title = 'STILLSEEN',
    eyebrow = 'AUTONOMOUS SURVIVAL SYSTEM',
    subtitle = '자동 무장을 구축하고, 끝없이 살아남아라',
    busy = false,
  } = props
  const lobbyId = useId()
  const safeCurrency = Number.isFinite(currency)
    ? Math.max(0, Math.floor(currency))
    : 0
  const [showcasedWeaponId, setShowcasedWeaponId] = useState(
    arsenalWeapons[0]?.id ?? '',
  )
  const [recordsScope, setRecordsScope] = useState<'local' | 'global'>('local')
  const showcasedWeapon =
    arsenalWeapons.find((weapon) => weapon.id === showcasedWeaponId) ??
    arsenalWeapons[0]
  const previewContent = preview ?? (
    <p className="stillseen-lobby-preview__fallback">
      오퍼레이터 전투 형상을 준비하는 중입니다.
    </p>
  )

  const handleTabKeyDown = (
    event: ReactKeyboardEvent<HTMLButtonElement>,
    currentIndex: number,
  ) => {
    let nextIndex: number | null = null
    if (event.key === 'ArrowRight' || event.key === 'ArrowDown') {
      nextIndex = (currentIndex + 1) % LOBBY_TABS.length
    } else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') {
      nextIndex = (currentIndex - 1 + LOBBY_TABS.length) % LOBBY_TABS.length
    } else if (event.key === 'Home') {
      nextIndex = 0
    } else if (event.key === 'End') {
      nextIndex = LOBBY_TABS.length - 1
    }

    if (nextIndex === null) return
    event.preventDefault()
    const nextTab = LOBBY_TABS[nextIndex]
    onTabChange(nextTab.id)
    event.currentTarget.parentElement
      ?.querySelector<HTMLButtonElement>(`[data-lobby-tab="${nextTab.id}"]`)
      ?.focus()
  }

  /**
   * Arrow-key movement inside a chip group.
   *
   * The tab strip above has always done this; the SECTOR and THREAT groups
   * declared `role="radiogroup"` and then behaved like nine separate buttons,
   * which is both wrong for the role and hostile in practice — eleven tab stops
   * between arriving at the deploy cluster and reaching the launch button.
   * A radio group is one stop, and the arrows move within it.
   */
  const handleChipKeyDown = <T,>(
    event: ReactKeyboardEvent<HTMLButtonElement>,
    options: readonly T[],
    currentIndex: number,
    select: (option: T) => void,
  ) => {
    let nextIndex: number | null = null
    if (event.key === 'ArrowRight' || event.key === 'ArrowDown') {
      nextIndex = (currentIndex + 1) % options.length
    } else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') {
      nextIndex = (currentIndex - 1 + options.length) % options.length
    } else if (event.key === 'Home') {
      nextIndex = 0
    } else if (event.key === 'End') {
      nextIndex = options.length - 1
    }

    if (nextIndex === null) return
    event.preventDefault()
    // Selection follows focus, which is the expected behaviour for a radio
    // group and is safe here: both choices are free to change until launch.
    select(options[nextIndex])
    const siblings = event.currentTarget.parentElement?.children
    const next = siblings?.[nextIndex]
    if (next instanceof HTMLButtonElement) next.focus()
  }

  return (
    <main
      className="stillseen-ui stillseen-lobby"
      aria-label="STILLSEEN 생존 코어"
      data-active-tab={activeTab}
      data-survival-ui="true"
      data-testid="title-screen"
    >
      <div
        className={cx(
          'stillseen-lobby__scene',
          activeTab !== 'expedition' && 'stillseen-lobby__scene--dormant',
        )}
        data-testid={activeTab === 'expedition' ? 'lobby-preview' : undefined}
        aria-label="오퍼레이터와 스타터 무기 미리보기"
        aria-hidden={activeTab !== 'expedition' || undefined}
      >
        {activeTab === 'expedition' ? (
          <>
            {previewContent}
            <div
              className="ss-lobby-live-feed"
              data-testid="lobby-live-feed"
              aria-hidden="true"
            >
              <span
                className="ss-lobby-live-feed__reticle"
                data-testid="lobby-live-feed-reticle"
              />
              <span
                className="ss-lobby-live-feed__label"
                data-testid="lobby-live-feed-label"
              >
                OPERATOR FEED // LIVE
              </span>
            </div>
          </>
        ) : null}
      </div>
      <div className="stillseen-lobby__fog" aria-hidden="true" />

      <div className="stillseen-lobby__frame" data-testid="lobby-screen">
        {/*
          The title block is gone from the header on purpose: the operative in
          the middle of the frame is the identity, and a wordmark beside the
          tabs pushed them off-centre. `title`/`eyebrow`/`subtitle` remain the
          screen's accessible name and its document heading, so they are kept
          for assistive tech rather than drawn.
        */}
        <h1 className="stillseen-sr-only">{title}</h1>
        <p className="stillseen-sr-only">
          {eyebrow} · {subtitle}
        </p>

        <header className="stillseen-lobby__header">
          <nav
            className="stillseen-lobby__tabs"
            role="tablist"
            aria-label="생존 코어 메뉴"
            aria-orientation="horizontal"
          >
            {LOBBY_TABS.map((tab, index) => {
              const selected = activeTab === tab.id
              return (
                <button
                  key={tab.id}
                  type="button"
                  id={`${lobbyId}-${tab.id}-tab`}
                  className="stillseen-lobby__tab"
                  role="tab"
                  aria-selected={selected}
                  aria-controls={`${lobbyId}-${tab.id}-panel`}
                  tabIndex={selected ? 0 : -1}
                  data-lobby-tab={tab.id}
                  data-testid={`lobby-tab-${tab.id}`}
                  onClick={() => onTabChange(tab.id)}
                  onKeyDown={(event) => handleTabKeyDown(event, index)}
                >
                  <small>{tab.eyebrow}</small>
                  <span>{tab.label}</span>
                </button>
              )
            })}
          </nav>

          <div className="stillseen-lobby__meta">
            {cloudAccount ? (
              <button
                type="button"
                className="ss-cloud-account"
                data-signed-in={cloudAccount.signedIn || undefined}
                data-testid="cloud-account-button"
                title={cloudAccount.error ?? cloudAccount.statusLabel}
                onClick={
                  cloudAccount.signedIn
                    ? cloudAccount.onSignOut
                    : cloudAccount.onSignIn
                }
              >
                <span aria-hidden="true">G</span>
                <span>
                  <strong>
                    {cloudAccount.signedIn
                      ? cloudAccount.displayName
                      : 'Google 로그인'}
                  </strong>
                  <small>{cloudAccount.statusLabel}</small>
                </span>
              </button>
            ) : null}
            <div
              className="stillseen-system-status ss-lobby-core-status"
              aria-label="생존 시스템 정상"
              data-testid="survival-core-status"
            >
              <span aria-hidden="true" />
              <span>
                <strong>SURVIVAL CORE</strong>
                <small>생존 시스템 정상</small>
              </span>
            </div>
            <div
              className="stillseen-lobby__currency"
              aria-label={`데이터 파편 ${safeCurrency}`}
              data-testid="lobby-currency"
            >
              <span
                className="stillseen-lobby__currency-mark"
                aria-hidden="true"
              />
              <span>데이터 파편</span>
              <data value={safeCurrency}>
                {safeCurrency.toLocaleString('ko-KR')}
              </data>
            </div>
            {onOpenSettings ? (
              <GameButton
                variant="ghost"
                className="stillseen-lobby__settings"
                onClick={onOpenSettings}
                disabled={busy}
                testId="open-settings-button"
              >
                설정
              </GameButton>
            ) : null}
          </div>
        </header>

        <div
          className={cx(
            'stillseen-lobby__announcement',
            announcement.length === 0 && 'stillseen-sr-only',
          )}
          role="status"
          aria-live="polite"
          aria-atomic="true"
          data-testid="lobby-announcement"
        >
          {announcement || ' '}
        </div>

        <div className="stillseen-lobby__panels">
          <section
            id={`${lobbyId}-expedition-panel`}
            className="stillseen-lobby__panel stillseen-lobby__panel--expedition"
            role="tabpanel"
            aria-labelledby={`${lobbyId}-expedition-tab`}
            hidden={activeTab !== 'expedition'}
            tabIndex={0}
            data-testid="lobby-panel-expedition"
          >
            <div className="ss-lobby-survival-briefing">
              <header>
                <p className="stillseen-eyebrow">ENDLESS SURVIVAL</p>
                <h2>단일 무한 생존전</h2>
                <p>
                  5분마다 보스가 출현합니다. 20분 이후에도 적의 밀도와 강도는
                  계속 상승하며 생존전은 끝없이 이어집니다.
                </p>
              </header>

              <ol
                className="ss-lobby-boss-timeline"
                aria-label="보스 출현 타임라인"
                data-testid="boss-timeline"
              >
                {BOSS_TIMELINE.map((minute, index) => (
                  <li key={minute}>
                    <span>{String(minute).padStart(2, '0')}:00</span>
                    <strong>보스 {index + 1}</strong>
                    <small>{minute === 20 ? '5분 반복' : '위협 상승'}</small>
                  </li>
                ))}
              </ol>

              <label className="stillseen-lobby-seed ss-lobby-seed">
                <span>생존전 시드</span>
                <input
                  value={seed}
                  onChange={(event) =>
                    onSeedChange(event.currentTarget.value.slice(0, 40))
                  }
                  maxLength={40}
                  spellCheck={false}
                  autoComplete="off"
                  data-testid="seed-input"
                  aria-label="생존전 시드"
                />
              </label>

              {onTutorialEnabledChange ? (
                <button
                  type="button"
                  className="stillseen-lobby-tutorial-toggle"
                  role="switch"
                  aria-checked={tutorialEnabled}
                  onClick={() => onTutorialEnabledChange(!tutorialEnabled)}
                  disabled={busy}
                  data-testid="tutorial-toggle"
                >
                  <span aria-hidden="true" />
                  <span>
                    <strong>생존 시스템 튜토리얼</strong>
                    <small>
                      이동, 자동 무장, XP, 레벨업을 첫 런에 안내합니다.
                    </small>
                  </span>
                </button>
              ) : null}
            </div>
          </section>

          <section
            id={`${lobbyId}-loadout-panel`}
            className="stillseen-lobby__panel ss-lobby-arsenal-panel"
            role="tabpanel"
            aria-labelledby={`${lobbyId}-loadout-tab`}
            hidden={activeTab !== 'loadout'}
            tabIndex={0}
            data-testid="lobby-panel-loadout"
          >
            {arsenalWeapons.length > 0 ? (
              <div className="ss-lobby-catalog">
                <div className="stillseen-lobby-section-heading">
                  <div>
                    <p className="stillseen-eyebrow">WEAPON CATALOG</p>
                    <h2>무장 도감</h2>
                  </div>
                  <p>각 무장의 해금 상태와 운용 개요를 빠르게 확인합니다.</p>
                </div>
                <div className="ss-lobby-catalog__body">
                  <div className="ss-lobby-catalog__side">
                    <ul
                      className="ss-lobby-catalog__list"
                      aria-label="무장 도감"
                      data-testid="weapon-catalog-list"
                    >
                      {arsenalWeapons.map((weapon) => (
                        <li key={weapon.id}>
                          <button
                            type="button"
                            aria-pressed={weapon.id === showcasedWeaponId}
                            data-locked={!weapon.unlocked && !weapon.issued}
                            data-testid={`weapon-catalog-${weapon.id}`}
                            onClick={() => setShowcasedWeaponId(weapon.id)}
                          >
                            <strong>{weapon.name}</strong>
                            <small>
                              {weapon.issued
                                ? '지급'
                                : weapon.unlocked
                                  ? '해금됨'
                                  : '미해금'}
                            </small>
                          </button>
                        </li>
                      ))}
                    </ul>
                    <p
                      className="ss-lobby-catalog__blurb"
                      data-testid="weapon-catalog-blurb"
                    >
                      {showcasedWeapon?.description ?? ''}
                    </p>
                  </div>
                </div>
              </div>
            ) : null}
          </section>

          <section
            id={`${lobbyId}-upgrade-panel`}
            className="stillseen-lobby__panel ss-lobby-unlocks-panel"
            role="tabpanel"
            aria-labelledby={`${lobbyId}-upgrade-tab`}
            hidden={activeTab !== 'upgrade'}
            tabIndex={0}
            data-testid="lobby-panel-upgrade"
          >
            <div className="stillseen-lobby-section-heading">
              <div>
                <p className="stillseen-eyebrow">CONTENT CATALOG</p>
                <h2>무기·패시브 해금</h2>
              </div>
              <p>
                데이터 파편으로 새로운 콘텐츠를 해금합니다. 해금한 항목은 다음
                런부터 레벨업 선택지에 등장하며, 각 항목은 명확한 장점과 단점을
                가집니다.
              </p>
            </div>
            {contentUnlocks.length > 0 ? (
              <div
                className="ss-lobby-unlock-grid"
                data-testid="content-unlock-grid"
              >
                {contentUnlocks.map((content) => (
                  <ContentUnlockCard
                    key={content.id}
                    content={content}
                    currency={safeCurrency}
                    busy={busy}
                    onUnlock={onUnlockContent}
                  />
                ))}
              </div>
            ) : (
              <p className="ss-lobby-empty" role="status">
                해금 카탈로그를 동기화하는 중입니다.
              </p>
            )}

            {permanentUpgrades.length > 0 ? (
              <>
                <div className="stillseen-lobby-section-heading">
                  <div>
                    <p className="stillseen-eyebrow">OPERATIVE BASELINE</p>
                    <h2>영구 능력 강화</h2>
                  </div>
                  <p>
                    해금이 선택지를 늘린다면, 이쪽은 출격하는 오퍼레이터 자체를
                    올립니다. 강화한 단계는 사망해도 사라지지 않고 모든 런에
                    적용됩니다.
                  </p>
                </div>
                <div
                  className="ss-lobby-stat-grid"
                  data-testid="permanent-stat-grid"
                >
                  {permanentUpgrades.map((upgrade) => (
                    <PermanentStatCard
                      key={upgrade.id}
                      upgrade={upgrade}
                      currency={safeCurrency}
                      busy={busy}
                      onPurchase={onPurchasePermanentUpgrade}
                    />
                  ))}
                </div>
              </>
            ) : null}
          </section>

          <section
            id={`${lobbyId}-records-panel`}
            className="stillseen-lobby__panel ss-lobby-records-panel"
            role="tabpanel"
            aria-labelledby={`${lobbyId}-records-tab`}
            hidden={activeTab !== 'records'}
            tabIndex={0}
            data-testid="lobby-panel-records"
          >
            <div className="stillseen-lobby-section-heading">
              <div>
                <p className="stillseen-eyebrow">SURVIVAL LEDGER</p>
                <h2>생존 기록</h2>
              </div>
              <p>
                생존 시간과 격파한 보스가 기록의 핵심입니다. 20분 이후부터는 매
                5분이 새로운 한계가 됩니다.
              </p>
            </div>
            <div
              className="ss-record-scope"
              role="tablist"
              aria-label="기록 범위"
            >
              <button
                type="button"
                role="tab"
                aria-selected={recordsScope === 'local'}
                onClick={() => setRecordsScope('local')}
              >
                내 기록
              </button>
              <button
                type="button"
                role="tab"
                aria-selected={recordsScope === 'global'}
                onClick={() => setRecordsScope('global')}
              >
                글로벌 TOP 10
              </button>
            </div>
            {recordsScope === 'local' && runRecords.length === 0 ? (
              <p className="stillseen-lobby-records__empty">
                아직 정산된 생존전이 없습니다. 첫 런을 마치면 생존 시간과 보스
                기록이 남습니다.
              </p>
            ) : recordsScope === 'local' ? (
              <ol className="stillseen-lobby-records" data-testid="run-records">
                {runRecords.map((record) => (
                  <li
                    key={`${record.rank}-${record.dateLabel}-${record.score}`}
                  >
                    <span className="stillseen-lobby-records__rank">
                      {String(record.rank).padStart(2, '0')}
                    </span>
                    <strong className="stillseen-lobby-records__score">
                      {formatSurvivalTime(record.survivalSeconds)}
                    </strong>
                    <span className="stillseen-lobby-records__meta">
                      보스 {Math.max(0, record.bossKills ?? 0)} · LV{' '}
                      {Math.max(1, record.level ?? 1)} ·{' '}
                      {Math.max(0, record.score).toLocaleString('ko-KR')}점
                    </span>
                    <span className="stillseen-lobby-records__date">
                      {record.dateLabel}
                    </span>
                  </li>
                ))}
              </ol>
            ) : !cloudAccount?.signedIn ? (
              <div className="stillseen-lobby-records__empty">
                <p>Google 로그인 후 글로벌 TOP 10을 확인할 수 있습니다.</p>
                <GameButton variant="ghost" onClick={cloudAccount?.onSignIn}>
                  Google 로그인
                </GameButton>
              </div>
            ) : globalRecordsStatus === 'loading' ||
              globalRecordsStatus === 'idle' ? (
              <p className="stillseen-lobby-records__empty" role="status">
                글로벌 기록을 불러오는 중입니다.
              </p>
            ) : globalRecordsStatus === 'error' ? (
              <p className="stillseen-lobby-records__empty" role="status">
                글로벌 기록을 불러오지 못했습니다. 로컬 기록은 안전합니다.
              </p>
            ) : globalRunRecords.length === 0 ? (
              <p className="stillseen-lobby-records__empty">
                아직 등록된 글로벌 기록이 없습니다.
              </p>
            ) : (
              <ol
                className="stillseen-lobby-records"
                data-testid="global-run-records"
              >
                {globalRunRecords.map((record) => (
                  <li
                    key={`${record.rank}-${record.displayName}-${record.score}`}
                  >
                    <span className="stillseen-lobby-records__rank">
                      {String(record.rank).padStart(2, '0')}
                    </span>
                    <strong className="stillseen-lobby-records__score">
                      {formatSurvivalTime(record.survivalSeconds)}
                    </strong>
                    <span className="stillseen-lobby-records__meta">
                      {record.displayName} · 보스{' '}
                      {Math.max(0, record.bossKills ?? 0)} · LV{' '}
                      {Math.max(1, record.level ?? 1)}
                    </span>
                    <span className="stillseen-lobby-records__date">
                      위협 {record.modeLabel}
                    </span>
                  </li>
                ))}
              </ol>
            )}
          </section>
        </div>

        {/*
          Bottom right, kept clear of the launch decision: the standing board.
          Local run history today, and the slot a networked leaderboard drops
          into — which is why it is always on screen rather than living behind
          the records tab.
        */}
        <aside
          className="ss-lobby-standings"
          aria-label="생존 순위"
          data-testid="lobby-standings"
        >
          <header>
            <p className="stillseen-eyebrow">SURVIVAL RANKING</p>
            <span>LOCAL</span>
          </header>
          {runRecords.length === 0 ? (
            <p className="ss-lobby-empty" role="status">
              아직 기록이 없습니다. 첫 생존전을 마치면 여기에 남습니다.
            </p>
          ) : (
            <ol data-testid="lobby-standings-list">
              {runRecords.slice(0, STANDINGS_LIMIT).map((record) => (
                <li key={`${record.rank}-${record.dateLabel}-${record.score}`}>
                  <span>{String(record.rank).padStart(2, '0')}</span>
                  <strong>{formatSurvivalTime(record.survivalSeconds)}</strong>
                  <small>
                    LV {Math.max(1, record.level ?? 1)} · 보스{' '}
                    {Math.max(0, record.bossKills ?? 0)}
                  </small>
                </li>
              ))}
            </ol>
          )}
          <small className="ss-lobby-standings__note">
            전체 순위는 준비 중입니다. 지금은 이 기기의 기록만 표시합니다.
          </small>
        </aside>

        {/*
          The deploy cluster, bottom left. Everything the player commits to —
          the sector, the threat rank, the contract they are accepting, and the
          button that spends all three — sits in one corner so the eye never
          has to leave the button to find what it is about to agree to.
        */}
        <div className="ss-lobby-deploy" data-testid="lobby-deploy">
          {arenaOptions.length > 0 ? (
            <div className="ss-lobby-chip-row">
              <span className="stillseen-eyebrow" id={`${lobbyId}-arena-label`}>
                SECTOR
              </span>
              <div
                className="ss-lobby-chips"
                role="radiogroup"
                aria-labelledby={`${lobbyId}-arena-label`}
                data-testid="arena-selector"
              >
                {arenaOptions.map((arena, index) => {
                  const checked = selectedArenaId === arena.id
                  return (
                    <button
                      key={arena.id}
                      type="button"
                      role="radio"
                      aria-checked={checked}
                      // Roving: the group is one tab stop, not one per arena.
                      tabIndex={
                        checked || (!selectedArenaId && index === 0) ? 0 : -1
                      }
                      disabled={busy || !onArenaSelect}
                      onClick={() => onArenaSelect?.(arena.id)}
                      onKeyDown={(event) =>
                        handleChipKeyDown(
                          event,
                          arenaOptions,
                          index,
                          (option) => onArenaSelect?.(option.id),
                        )
                      }
                      data-testid={`arena-${arena.id}`}
                    >
                      <small>{arena.biomeLabel}</small>
                      <span>{arena.name}</span>
                    </button>
                  )
                })}
              </div>
            </div>
          ) : (
            <div className="ss-lobby-sector-lock" data-testid="arena-selector">
              <span className="stillseen-eyebrow">SECTOR</span>
              <div>
                <small>CONTAINMENT ZONE</small>
                <strong>격리 구역</strong>
              </div>
            </div>
          )}

          {difficultyOptions.length > 0 ? (
            <div className="ss-lobby-chip-row">
              <span
                className="stillseen-eyebrow"
                id={`${lobbyId}-difficulty-label`}
              >
                THREAT
              </span>
              <div
                className="ss-lobby-chips"
                role="radiogroup"
                aria-labelledby={`${lobbyId}-difficulty-label`}
                data-testid="difficulty-selector"
              >
                {difficultyOptions.map((option, index) => {
                  const checked = selectedDifficulty === option.rank
                  return (
                    <button
                      key={option.rank}
                      type="button"
                      role="radio"
                      aria-checked={checked}
                      tabIndex={
                        checked ||
                        (selectedDifficulty === undefined && index === 0)
                          ? 0
                          : -1
                      }
                      disabled={
                        busy || option.locked === true || !onDifficultySelect
                      }
                      onClick={() => onDifficultySelect?.(option.rank)}
                      onKeyDown={(event) =>
                        handleChipKeyDown(
                          event,
                          difficultyOptions,
                          index,
                          (next) => {
                            if (next.locked === true) return
                            onDifficultySelect?.(next.rank)
                          },
                        )
                      }
                      data-testid={`difficulty-${option.rank}`}
                    >
                      <small>{option.payoutLabel}</small>
                      <span>{option.name}</span>
                    </button>
                  )
                })}
              </div>
            </div>
          ) : null}

          <dl className="ss-lobby-contract" data-testid="survival-contract">
            <div>
              <dt>런 형식</dt>
              <dd>단일 무한 생존</dd>
            </div>
            <div>
              <dt>20분 이후</dt>
              <dd>계속 진행</dd>
            </div>
            <div>
              <dt>보스 주기</dt>
              <dd>5분</dd>
            </div>
            <div>
              <dt>시작 무장</dt>
              <dd>출격 직전 1개 선택</dd>
            </div>
          </dl>

          <GameButton
            variant="primary"
            className="ss-lobby-deploy__launch"
            onClick={onStart}
            disabled={busy || seed.trim().length === 0}
            autoFocus={activeTab === 'expedition'}
            testId="start-game-button"
          >
            {busy ? '생존 구역 연결 중…' : '생존전 개시'}
          </GameButton>
        </div>

        <footer className="stillseen-lobby__footer">
          <p>
            런에서 얻은 무기와 패시브는 종료 시 초기화되며, 해금 콘텐츠와 데이터
            파편은 남습니다.
          </p>
          <details className="stillseen-lobby-credits">
            <summary>에셋 크레딧</summary>
            <div className="stillseen-lobby-credits__panel">
              {credits.length > 0 ? (
                <ul>
                  {credits.map((credit) => (
                    <li key={credit.id}>
                      {credit.href ? (
                        <a href={credit.href} target="_blank" rel="noreferrer">
                          {credit.label}
                        </a>
                      ) : (
                        <span>{credit.label}</span>
                      )}
                      {credit.creator ? <small>{credit.creator}</small> : null}
                      <code>{credit.license}</code>
                    </li>
                  ))}
                </ul>
              ) : (
                <p>사용한 외부 에셋의 출처와 라이선스를 확인할 수 있습니다.</p>
              )}
              <a
                className="stillseen-lobby-credits__manifest"
                href={creditsHref}
                target="_blank"
                rel="noreferrer"
                data-testid="asset-credits-link"
              >
                전체 라이선스 기록
              </a>
            </div>
          </details>
        </footer>
      </div>
    </main>
  )
}
