import type { DifficultyRank, GameMode } from '../game'

/**
 * Local run leaderboard.
 *
 * Stored beside the save under its own key — the same sidecar pattern as the
 * vision-assist preference — so the board can evolve without touching the
 * versioned save schema or its migration chain. Records survive a save reset
 * for the same reason a reset should not erase someone's best run.
 */
export interface RunRecord {
  readonly score: number
  readonly survivalSeconds?: number
  readonly bossKills?: number
  readonly level?: number
  /** 1-based deepest sector the run reached. */
  readonly sector: number
  readonly mode: GameMode
  readonly difficulty: DifficultyRank
  readonly won: boolean
  /** ISO timestamp of the settlement. */
  readonly at: string
}

const RECORDS_KEY = 'stillseen.records.v1'
const RECORDS_UPDATED_AT_KEY = 'stillseen.records.updated.v1'
export const RUN_RECORD_LIMIT = 10

export function isRunRecord(value: unknown): value is RunRecord {
  if (typeof value !== 'object' || value === null) return false
  const record = value as Record<string, unknown>
  return (
    typeof record.score === 'number' &&
    Number.isFinite(record.score) &&
    record.score >= 0 &&
    (record.survivalSeconds === undefined ||
      (typeof record.survivalSeconds === 'number' &&
        Number.isFinite(record.survivalSeconds) &&
        record.survivalSeconds >= 0)) &&
    (record.bossKills === undefined ||
      (typeof record.bossKills === 'number' &&
        Number.isInteger(record.bossKills) &&
        record.bossKills >= 0)) &&
    (record.level === undefined ||
      (typeof record.level === 'number' &&
        Number.isInteger(record.level) &&
        record.level >= 1)) &&
    typeof record.sector === 'number' &&
    Number.isInteger(record.sector) &&
    record.sector >= 1 &&
    (record.mode === 'standard' ||
      record.mode === 'endless' ||
      record.mode === 'daily') &&
    typeof record.difficulty === 'number' &&
    Number.isInteger(record.difficulty) &&
    record.difficulty >= 1 &&
    record.difficulty <= 5 &&
    typeof record.won === 'boolean' &&
    typeof record.at === 'string'
  )
}

/** Best runs first; ties broken by deeper sector, then recency. */
export function compareRunRecords(a: RunRecord, b: RunRecord): number {
  const survivalDifference = (b.survivalSeconds ?? 0) - (a.survivalSeconds ?? 0)
  if (survivalDifference !== 0) return survivalDifference
  if (a.score !== b.score) return b.score - a.score
  if (a.sector !== b.sector) return b.sector - a.sector
  return b.at.localeCompare(a.at)
}

export function readRunRecords(): readonly RunRecord[] {
  try {
    const raw = window.localStorage.getItem(RECORDS_KEY)
    if (raw === null) return []
    const parsed: unknown = JSON.parse(raw)
    if (!Array.isArray(parsed)) return []
    return parsed
      .filter(isRunRecord)
      .sort(compareRunRecords)
      .slice(0, RUN_RECORD_LIMIT)
  } catch {
    return []
  }
}

export function parseRunRecords(raw: string): readonly RunRecord[] {
  try {
    const parsed: unknown = JSON.parse(raw)
    if (!Array.isArray(parsed)) return []
    return parsed
      .filter(isRunRecord)
      .sort(compareRunRecords)
      .slice(0, RUN_RECORD_LIMIT)
  } catch {
    return []
  }
}

export function replaceRunRecords(
  records: readonly RunRecord[],
): readonly RunRecord[] {
  const next = records
    .filter(isRunRecord)
    .sort(compareRunRecords)
    .slice(0, RUN_RECORD_LIMIT)
  try {
    const serialized = JSON.stringify(next)
    if (window.localStorage.getItem(RECORDS_KEY) !== serialized) {
      window.localStorage.setItem(RECORDS_KEY, serialized)
      window.localStorage.setItem(RECORDS_UPDATED_AT_KEY, String(Date.now()))
    }
  } catch {
    // The in-memory list still lets the current session continue.
  }
  return next
}

export function readRunRecordsUpdatedAt(): number {
  try {
    const value = Number(window.localStorage.getItem(RECORDS_UPDATED_AT_KEY))
    return Number.isFinite(value) && value > 0 ? value : 0
  } catch {
    return 0
  }
}

/**
 * Inserts a finished run and returns the updated board along with the rank
 * the run landed at (1-based), or null if it fell off the table.
 */
export function recordRun(record: RunRecord): {
  readonly records: readonly RunRecord[]
  readonly rank: number | null
} {
  const records = [...readRunRecords(), record]
    .sort(compareRunRecords)
    .slice(0, RUN_RECORD_LIMIT)
  replaceRunRecords(records)
  const index = records.indexOf(record)
  return { records, rank: index === -1 ? null : index + 1 }
}
