import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type CSSProperties,
} from 'react'

import { touchInput } from '../runtime/inputActions'
import { useGameStore } from '../runtime/gameStore'
import './touch-controls.css'

interface TouchStickProps {
  readonly label: string
  readonly onVector: (x: number, z: number) => void
}

function TouchStick({ label, onVector }: TouchStickProps) {
  const pointerId = useRef<number | null>(null)
  const [vector, setVector] = useState({ x: 0, z: 0 })

  const update = useCallback(
    (element: HTMLElement, clientX: number, clientY: number) => {
      const bounds = element.getBoundingClientRect()
      const radius = Math.max(1, Math.min(bounds.width, bounds.height) / 2)
      let x = (clientX - (bounds.left + bounds.width / 2)) / radius
      let z = (clientY - (bounds.top + bounds.height / 2)) / radius
      const length = Math.hypot(x, z)
      if (length > 1) {
        x /= length
        z /= length
      }
      setVector({ x, z })
      onVector(x, z)
    },
    [onVector],
  )

  const release = useCallback(() => {
    pointerId.current = null
    setVector({ x: 0, z: 0 })
    onVector(0, 0)
  }, [onVector])

  return (
    <div
      className="stillseen-touch-stick"
      role="group"
      aria-label={label}
      onPointerDown={(event) => {
        event.preventDefault()
        pointerId.current = event.pointerId
        event.currentTarget.setPointerCapture(event.pointerId)
        update(event.currentTarget, event.clientX, event.clientY)
      }}
      onPointerMove={(event) => {
        if (pointerId.current !== event.pointerId) return
        update(event.currentTarget, event.clientX, event.clientY)
      }}
      onPointerUp={(event) => {
        if (pointerId.current !== event.pointerId) return
        release()
      }}
      onPointerCancel={release}
    >
      <span
        className="stillseen-touch-stick__knob"
        style={{
          transform: `translate(${vector.x * 42}%, ${vector.z * 42}%)`,
        }}
      />
      <small>{label}</small>
    </div>
  )
}

export interface TouchControlsProps {
  readonly phase: 'playing' | 'paused'
  readonly onTogglePause: () => void
}

/** Mobile is intentionally landscape-only across title, lobby, and combat. */
export function LandscapeOrientationGate() {
  return (
    <div
      className="stillseen-landscape-gate"
      role="status"
      aria-live="polite"
      data-testid="landscape-orientation-gate"
    >
      <span className="stillseen-landscape-gate__device" aria-hidden="true" />
      <strong>가로 모드가 필요합니다</strong>
      <span>기기를 가로로 돌리면 계속할 수 있습니다.</span>
    </div>
  )
}

export function TouchControls({ phase, onTogglePause }: TouchControlsProps) {
  const pausedForOrientation = useRef(false)
  const dashCooldownProgress = useGameStore(
    (state) => state.dashCooldownProgress,
  )

  useEffect(() => () => touchInput.reset(), [])

  useEffect(() => {
    if (typeof window.matchMedia !== 'function') return
    const query = window.matchMedia(
      '(pointer: coarse) and (orientation: portrait)',
    )
    const sync = () => {
      if (query.matches && phase === 'playing') {
        pausedForOrientation.current = true
        touchInput.reset()
        onTogglePause()
      } else if (
        !query.matches &&
        phase === 'paused' &&
        pausedForOrientation.current
      ) {
        pausedForOrientation.current = false
        onTogglePause()
      }
    }
    sync()
    query.addEventListener('change', sync)
    return () => query.removeEventListener('change', sync)
  }, [onTogglePause, phase])

  return (
    <>
      {phase === 'playing' ? (
        <aside className="stillseen-touch-controls" aria-label="터치 조작">
          <TouchStick label="이동" onVector={touchInput.setMove} />
          <TouchStick label="시선" onVector={touchInput.setAim} />
          <button
            type="button"
            className="stillseen-touch-dash"
            disabled={dashCooldownProgress < 1}
            onPointerDown={(event) => {
              event.preventDefault()
              touchInput.pressDash()
            }}
            onClick={touchInput.pressDash}
            aria-label="대시"
            style={
              {
                '--dash-progress': `${dashCooldownProgress * 360}deg`,
              } as CSSProperties
            }
          >
            DASH
          </button>
          <button
            type="button"
            className="stillseen-touch-pause"
            onClick={onTogglePause}
            aria-label="일시 정지"
          >
            Ⅱ
          </button>
        </aside>
      ) : null}
    </>
  )
}
