  useEffect(() => {
    if (phase !== 'booting' || bootAttempt === 0) return
    const controller = new AbortController()
    bootController.current = controller
    let active = true
    const waitForScene = async (
      report: (value: number, detail?: string) => void,
    ) => {
      shaderProgressReporter.current = report
      if (sceneReady.current) {
        report(1, '렌더러 준비 완료')
        return
      }
      await new Promise<void>((resolve, reject) => {
        const finish = () => {
          controller.signal.removeEventListener('abort', abort)
          resolve()
        }
        const abort = () => {
          sceneReadyWaiters.current.delete(finish)
          reject(controller.signal.reason)
        }
        sceneReadyWaiters.current.add(finish)
        controller.signal.addEventListener('abort', abort, { once: true })
      })
      report(1, '렌더러 준비 완료')
    }

    void runBootTasks(
      [
        {
          stage: 'system',
          label: BOOT_STAGE_LABELS.system,
          weight: 1,
          run: async ({ report }) => {
            serializeSave(saveRef.current)
            await Promise.resolve()
            report(1, '세이브 스키마 확인 완료')
          },
        },
        {
          stage: 'code',
          label: BOOT_STAGE_LABELS.code,
          weight: 2,
          run: async ({ report }) => {
            let loadedModules = 0
            const markModuleLoaded = (detail: string) => {
              loadedModules += 1
              report(loadedModules / 2, detail)
            }
            await Promise.all([
              loadGameSceneModule().then(() =>
                markModuleLoaded('전투 모듈 준비 완료'),
              ),
              loadLobbyPreviewModule().then(() =>
                markModuleLoaded('로비 3D 모듈 준비 완료'),
              ),
            ])
          },
        },
        {
          stage: 'audio',
          label: BOOT_STAGE_LABELS.audio,
          weight: 1,
          critical: false,
          run: async ({ signal, report }) => {
            await (audioBootPromise.current ?? audioEngine.unlock(signal))
            report(1, '효과음과 음악 준비 완료')
          },
        },
        {
          stage: 'assets',
          label: BOOT_STAGE_LABELS.assets,
          weight: 4,
          critical: false,
          run: (context) =>
            preloadAssetBundle(
              `${import.meta.env.BASE_URL}assets/asset-manifest.json`,
              `${import.meta.env.BASE_URL}assets/`,
              // `biome-1` is every enemy model. It was never preloaded, so the
              // first wave of a run — 1.4s in — triggered the fetch, the
              // meshopt decode, and the skeleton clone mid-fight, with the
              // procedural drone standing in until it landed.
              ['initial', 'biome-1'],
              context,
            ),
        },
        {
          stage: 'physics',
          label: BOOT_STAGE_LABELS.physics,
          weight: 1,
          run: async ({ report }) => {
            await import('@react-three/rapier')
            report(1, 'Rapier 물리 준비 완료')
          },
        },
        {
          stage: 'shaders',
          label: BOOT_STAGE_LABELS.shaders,
          weight: 3,
          run: ({ report }) => waitForScene(report),
        },
        {
          stage: 'finalizing',
          label: BOOT_STAGE_LABELS.finalizing,
          weight: 1,
          run: async ({ signal, report }) => {
            await waitForAnimationFrames(2, signal)
            report(1, '후처리 프레임 예열 완료')
          },
        },
      ],
      (update) => active && setBootProgress(update),
      controller.signal,
    )
      .then((result) => {
        if (!active || controller.signal.aborted) return
        shaderProgressReporter.current = null
        setBootWarnings(result.warnings)
        if (result.warnings.length > 0) {
          setAnnouncement(
            `일부 선택 기능을 불러오지 못해 대체 표현으로 실행합니다. (${result.warnings.length})`,
          )
        }
        enterLobby()
      })
      .catch((error: unknown) => {
        if (!active || controller.signal.aborted) return
        const message =
          error instanceof Error ? error.message : '게임 준비에 실패했습니다.'
        setBootError(message)
        useGameStore.getState().failLoading(message)
      })

    return () => {
      active = false
      shaderProgressReporter.current = null
      controller.abort()
    }
  }, [bootAttempt, enterLobby, phase])

  useEffect(() => {
    if (encounterEvent === null || phase !== 'playing') return
    const remainingMs = encounterCueRemainingMs.current
    const startedAt = Date.now()
    encounterCueStartedAt.current = startedAt
    const timer = window.setTimeout(() => {
      if (encounterCueEventId.current !== encounterEvent.id) return
      encounterCueEventId.current = null
      encounterCueRemainingMs.current = 0
      encounterCueStartedAt.current = null
      setEncounterEvent((current) =>
        current?.id === encounterEvent.id ? null : current,
      )
    }, remainingMs)
    return () => {
      window.clearTimeout(timer)
      if (
        encounterCueEventId.current === encounterEvent.id &&
        encounterCueStartedAt.current === startedAt
      ) {
        encounterCueRemainingMs.current = Math.max(
          0,
          remainingMs - (Date.now() - startedAt),
        )
        encounterCueStartedAt.current = null
      }
    }
  }, [encounterEvent, phase])

  useEffect(() => {
    if (
      generatedRun &&
      currentGeneratedRoom &&
      currentGeneratedRoom.depth >= 5 &&
      !moonBundleReady
    ) {
      void prepareMoonGarden()
    }
  }, [currentGeneratedRoom, generatedRun, moonBundleReady, prepareMoonGarden])

  useEffect(() => {
    if (phase !== 'expedition-loading' || roomPreparationKey === null) return
    if (currentGeneratedRoom?.biomeId === 'moon-garden' && !moonBundleReady) {
      void prepareMoonGarden()
      return
    }
    if (preparedSceneKey !== roomPreparationKey) return
    const controller = new AbortController()
    void waitForAnimationFrames(2, controller.signal)
      .then(() => transitionScreen(beginPlaying))
      .catch(() => undefined)
    return () => controller.abort()
  }, [
    beginPlaying,
    currentGeneratedRoom?.biomeId,
    moonBundleReady,
    phase,
    prepareMoonGarden,
    preparedSceneKey,
    roomPreparationKey,
    transitionScreen,
  ])

  useEffect(() => {
    const store = useGameStore.getState()
    store.setMasterVolume(save.settings.masterVolume)
    store.setMusicVolume(save.settings.musicVolume)
    store.setSfxVolume(save.settings.sfxVolume)
    const savedVisionAssist = readVisionAssist()
    if (savedVisionAssist !== null) {
      useGameStore.getState().setVisionAssist(savedVisionAssist)
    }
    // Only hydrate the runtime settings once. Later changes update both stores.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // Music kept looping in a background tab: nothing listened for visibility
  // and togglePause is audio-silent.
  useEffect(() => {
    const onVisibilityChange = () => {
      if (document.hidden) audioEngine.suspendForHiddenTab()
      else audioEngine.resumeFromHiddenTab()
    }
    document.addEventListener('visibilitychange', onVisibilityChange)
    return () =>
      document.removeEventListener('visibilitychange', onVisibilityChange)
  }, [])

  // The DOM layer already honours prefers-reduced-motion through CSS; without
  // this the WebGL layer would contradict it. Reduced motion removes camera
  // displacement and large transforms while keeping opacity, bloom, hit
  // flashes, and audio cues readable.
  useEffect(() => {
    const apply = (systemPrefersReduced: boolean) => {
      useGameStore
        .getState()
        .setReducedMotion(
          resolveReducedMotion(motionPreference, systemPrefersReduced),
        )
    }
    apply(systemPrefersReducedMotion())
    return watchReducedMotion(apply)
  }, [motionPreference])

  useEffect(() => {
    saveRef.current = save
  }, [save])

  useEffect(() => {
    if (!writeLocalSave(save)) return
    // Pruning the v1-v4 keys is migration cleanup, so it is only correct once
    // this session actually recovered a save. A session that fell back to
    // defaults must not delete what may be the only surviving copy.
    if (!initialSaveLoad.recovered) return
    try {
      removeMigratedSaveKeys()
    } catch {
      // The current-slot write succeeded; stale migration keys are harmless.
    }
  }, [save, initialSaveLoad.recovered])

  useEffect(() => {
    if (!settingsOpen) return
    const previousFocus = document.activeElement

    const closeSettings = (event: KeyboardEvent) => {
      if (event.code !== 'Escape' || event.repeat) return
      event.preventDefault()
      event.stopImmediatePropagation()
      setSettingsOpen(false)
    }

    window.addEventListener('keydown', closeSettings, true)
    return () => {
      window.removeEventListener('keydown', closeSettings, true)
      window.requestAnimationFrame(() => {
        const fallback = document.querySelector<HTMLElement>(
          '[data-testid="resume-game-button"], [data-testid="open-settings-button"]',
        )
        if (previousFocus instanceof HTMLElement && previousFocus.isConnected) {
          previousFocus.focus()
        } else {
          fallback?.focus()
        }
      })
    }
  }, [settingsOpen])

  useEffect(
    () => () => {
      moonBundleController.current?.abort()
    },
    [],
  )

  useEffect(
    () =>
      useGameStore.subscribe((state, previous) => {
        if (
          state.seed &&
          (state.mode === 'standard' || state.mode === 'endless') &&
          (state.seed !== previous.seed ||
            state.roomIndex !== previous.roomIndex ||
            state.runId !== previous.runId)
        ) {
          const chamber = state.roomIndex + 1
          setSave((current) => {
            const progressed = recordChamberProgress(
              current.meta,
              state.difficulty,
              chamber,
            )
            return progressed === current.meta
              ? current
              : { ...current, meta: progressed }
          })
        }

        // Death is the only ending. There is no victory phase to settle: the
        // arena never runs out, so a run is measured by how long it lasted.
        if (
          state.phase !== 'defeat' ||
          state.phase === previous.phase ||
          recordedSettlementRun.current === state.runId
        ) {
          return
        }

        recordedSettlementRun.current = state.runId
        // Every finished run lands on the local survival ledger, whatever
        // its mode — the board is the game's rank list.
        setRunRecords(
          recordRun({
            score: state.score,
            survivalSeconds: state.runElapsedSeconds,
            bossKills: state.bossKills,
            level: resolveLevel(state.experience).level,
            sector: Math.max(1, state.roomIndex + 1),
            mode: state.mode,
            difficulty: state.difficulty,
            won: false,
            at: new Date().toISOString(),
          }).records,
        )
        const checkpointShardGrant =
          (state.difficulty === 2 ? 10 : 5) + state.roomIndex * 2
        const payout =
          calculateRunPayout(state.score, state.difficulty) +
          checkpointShardGrant
        const previousBest =
          saveRef.current.meta.bestScoreByDifficulty[state.difficulty]
        setLastRunWasNewBest(state.score > previousBest)
        setLastRunPayout(payout)
        setAnnouncement(
          `임무 정산으로 데이터 파편 ${payout}개를 획득했습니다. 데이터 파편은 사망해도 보존됩니다.`,
        )
        setSave((current) => ({
          ...current,
          meta: {
            ...current.meta,
            currency: current.meta.currency + payout,
            bestScoreByDifficulty: {
              ...current.meta.bestScoreByDifficulty,
              [state.difficulty]: Math.max(
                current.meta.bestScoreByDifficulty[state.difficulty],
                state.score,
              ),
            },
          },
        }))
      }),
    [],
  )

  const uiSettings: UiSettings = {
    masterVolume: settings.masterVolume,
    musicVolume: settings.musicVolume,
    sfxVolume: settings.sfxVolume,
    visionAssistIntensity: settings.visionAssist,
    reducedMotion: settings.reducedMotion,
    gamepadVibration: settings.gamepadVibration,
  }

