    store.setMasterVolume(next.masterVolume)
    store.setMusicVolume(next.musicVolume)
    store.setSfxVolume(next.sfxVolume)
    store.setVisionAssist(next.visionAssistIntensity)
    store.setReducedMotion(next.reducedMotion)
    store.setGamepadVibration(next.gamepadVibration)
