import { DEFAULT_CONTROL_BINDINGS, type ControlBinding } from '../controls'
import { cx } from '../utils'

export type { ControlBinding }

export type InputDevice = 'keyboard' | 'gamepad'

export interface ControlsLegendProps {
  bindings?: readonly ControlBinding[]
  compact?: boolean
  inputDevice?: InputDevice
  className?: string
}

export function ControlsLegend({
  bindings = DEFAULT_CONTROL_BINDINGS,
  compact = false,
  inputDevice = 'keyboard',
  className,
}: ControlsLegendProps) {
  return (
    <section
      className={cx(
        'stillseen-ui stillseen-controls',
        compact && 'stillseen-controls--compact',
        className,
      )}
      aria-label="조작 안내"
      data-input-device={inputDevice}
      data-testid="controls-legend"
    >
      <h2 className="stillseen-sr-only">조작 안내</h2>
      <ul className="stillseen-controls__list">
        {bindings.map((binding) => (
          <li className="stillseen-controls__item" key={binding.id}>
            <span className="stillseen-controls__keys" aria-hidden="true">
              {(inputDevice === 'gamepad' && binding.gamepadKeys
                ? binding.gamepadKeys
                : binding.keys
              ).map((key) => (
                <kbd
                  key={key}
                  className="stillseen-input-glyph"
                  data-input-key={key.toLowerCase().replaceAll(' ', '-')}
                >
                  {key}
                </kbd>
              ))}
            </span>
            <span className="stillseen-controls__label">
              {binding.label}
              {binding.description ? (
                <small>{binding.description}</small>
              ) : null}
            </span>
            <span className="stillseen-sr-only">
              {(inputDevice === 'gamepad' && binding.gamepadKeys
                ? binding.gamepadKeys
                : binding.keys
              ).join(' 또는 ')}
              : {binding.label}
            </span>
          </li>
        ))}
      </ul>
    </section>
  )
}
