import type { RefObject } from 'react'

import './operator-feed-hud.css'

export interface OperatorFeedHudProps {
  readonly elementRef: RefObject<HTMLDivElement | null>
  readonly paused: boolean
}

/** Decorative observation frame; the scene owns its compositor transform. */
export function OperatorFeedHud({ elementRef, paused }: OperatorFeedHudProps) {
  return (
    <div
      ref={elementRef}
      className="ss-operator-feed"
      data-status={paused ? 'hold' : 'live'}
      data-visible="false"
      data-testid="operator-feed-hud"
      aria-hidden="true"
    >
      <span className="ss-operator-feed__scanlines" />
      <i className="ss-operator-feed__corner ss-operator-feed__corner--tl" />
      <i className="ss-operator-feed__corner ss-operator-feed__corner--tr" />
      <i className="ss-operator-feed__corner ss-operator-feed__corner--bl" />
      <i className="ss-operator-feed__corner ss-operator-feed__corner--br" />
      <span
        className="ss-operator-feed__reticle"
        data-testid="operator-feed-reticle"
      />
      <span
        className="ss-operator-feed__label"
        data-testid="operator-feed-label"
      >
        <b className="ss-operator-feed__label-full">OPERATOR FEED</b>
        <b className="ss-operator-feed__label-compact">OP FEED</b>
        <span>// {paused ? 'HOLD' : 'LIVE'}</span>
      </span>
    </div>
  )
}
