export interface HitVignetteProfile {
  readonly strength: number
  readonly opacity: number
  readonly midOpacity: number
  readonly tailOpacity: number
  readonly durationSeconds: number
  /** Normalized horizontal screen direction toward the source of the hit. */
  readonly directionX: number
  /** Normalized vertical screen direction toward the source of the hit. */
  readonly directionY: number
  /** Percentage position used to pin the directional edge arc. */
  readonly arcXPercent: number
  /** Percentage position used to pin the directional edge arc. */
  readonly arcYPercent: number
  readonly arcRotationDegrees: number
}

export type HitDirection = readonly [number, number, number]

/** Matches the in-scene throw and iris beat before the result card appears. */
export const LETHAL_HIT_VIGNETTE_SECONDS = 2.8

export function getHitVignetteDuration(
  profile: HitVignetteProfile,
  lethal: boolean,
): number {
  return lethal
    ? Math.max(profile.durationSeconds, LETHAL_HIT_VIGNETTE_SECONDS)
    : profile.durationSeconds
}

function finiteOrZero(value: number | undefined): number {
  return Number.isFinite(value) ? (value ?? 0) : 0
}

function normalizeScreenDirection(direction?: HitDirection): {
  x: number
  y: number
} {
  const worldX = finiteOrZero(direction?.[0])
  // The gameplay camera looks from +Z toward -Z, so +Z is screen-down.
  const screenY = finiteOrZero(direction?.[2])
  const length = Math.hypot(worldX, screenY)
  if (length < 0.000_001) return { x: 0, y: -1 }
  return { x: worldX / length, y: screenY / length }
}

export function getHitVignetteProfile(
  damage: number,
  maxHealth: number,
  reducedMotion: boolean,
  direction?: HitDirection,
): HitVignetteProfile {
  const ratio =
    Number.isFinite(damage) && Number.isFinite(maxHealth) && maxHealth > 0
      ? Math.max(0, damage) / maxHealth
      : 0
  const severity = Math.min(1, ratio / 0.45)
  const strength = 0.42 + severity * 0.58
  const opacity = reducedMotion
    ? 0.66 + severity * 0.18
    : 0.72 + severity * 0.24
  const screenDirection = normalizeScreenDirection(direction)

  return {
    strength,
    opacity,
    midOpacity: opacity * (0.48 + severity * 0.04),
    tailOpacity: opacity * (0.15 + severity * 0.05),
    durationSeconds: reducedMotion
      ? 0.9 + severity * 0.25
      : 1.15 + severity * 0.55,
    directionX: screenDirection.x,
    directionY: screenDirection.y,
    arcXPercent: 50 + screenDirection.x * 48,
    arcYPercent: 50 + screenDirection.y * 48,
    arcRotationDegrees:
      (Math.atan2(screenDirection.y, screenDirection.x) * 180) / Math.PI + 90,
  }
}
